// Detailed weapon viewmodels + remote guns with REAL image-based PBR textures.
// Texture assets: public/assets/textures/weapons/<key>.jpg + <key>_n.jpg (normal) + <key>_r.jpg (roughness),
// generated by scripts/texgen/gen.sh (z-ai image gen) and processed by scripts/texgen/process.py
// (2x2 mirror tileable, sobel normals, baked absolute roughness).
//
// Design goals:
//  - MeshStandardMaterial with albedo/normal/roughness maps for real PBR response
//  - graceful degradation: materials show flat fallback colors until textures load
//    (and keep them forever if the images 404)
//  - per-part texture repeat derived from geometry size (uniform texel density)
//  - material + geometry caches keep draw setup cheap; texture clones share one GPU upload
import * as THREE from 'three'
import type { TeamId, WeaponId } from './weapons'
import { WEAPONS } from './weapons'

export interface ViewModel {
  group: THREE.Group
  /** muzzle tip, local to group */
  tip: THREE.Vector3
  /** magazine (hidden mid-reload, dropped copy spawned by engine) */
  mag?: THREE.Group
  /** blowback part (pistol slide; on GLB vms the reciprocating top unit,
   * e.g. the AK's dust-cover assembly — Task 64). Engine drives position.z */
  slide?: THREE.Object3D
  /** second slide for dual berettas — engine alternates fire left/right */
  slideL?: THREE.Object3D
  /** AWP bolt assembly (cycle anim) */
  bolt?: THREE.Group
  /** shotgun fore-end pump (rack anim, Phase 6) */
  pump?: THREE.Group
  /** shell ejection port, local to group */
  eject?: THREE.Vector3
  /** C4 blinking LED */
  led?: THREE.Mesh
  /** grenade pin/lever assembly — engine rotates it out on throw (Phase 8) */
  pin?: THREE.Group
  muzzleLen?: number
}

export type TexKey =
  | 'steel_blued' | 'polymer_black' | 'wood_laminate' | 'enamel_od'
  | 'metal_dark' | 'glove_fabric' | 'pcb_green'

const TEX_DIR = '/assets/textures/weapons'

interface MatOpts {
  color?: number
  metalness?: number
  /** multiplies the baked roughness map once applied */
  roughnessMul?: number
  normalScale?: number
  /** texture tiles per meter override */
  density?: number
  rx?: number
  ry?: number
}

interface TexEntry {
  albedo: THREE.Texture
  normal: THREE.Texture
  rough: THREE.Texture
  ready: boolean
  pending: Array<{ mat: THREE.MeshStandardMaterial; rx: number; ry: number; o: MatOpts }>
}

const loader = new THREE.TextureLoader()
const texDB = new Map<TexKey, TexEntry>()

const FALLBACK: Record<TexKey, { color: number; metalness: number; roughness: number; density: number }> = {
  steel_blued:   { color: 0x33383d, metalness: 0.90, roughness: 0.40, density: 2.6 },
  polymer_black: { color: 0x232629, metalness: 0.15, roughness: 0.80, density: 7.0 },
  wood_laminate: { color: 0x8a5426, metalness: 0.05, roughness: 0.60, density: 2.8 },
  enamel_od:     { color: 0x4c5442, metalness: 0.35, roughness: 0.50, density: 2.6 },
  metal_dark:    { color: 0x2b2f33, metalness: 0.85, roughness: 0.55, density: 3.0 },
  glove_fabric:  { color: 0x1a1c1f, metalness: 0.00, roughness: 0.90, density: 6.5 },
  pcb_green:     { color: 0x1c3a26, metalness: 0.30, roughness: 0.60, density: 4.0 },
}

function getTex(key: TexKey): TexEntry {
  let e = texDB.get(key)
  if (e) return e
  let remaining = 3
  const onOne = () => {
    remaining--
    if (remaining <= 0) flush(key)
  }
  // onError also counts down -> failed loads keep the flat color fallback
  const load = (file: string) => loader.load(`${TEX_DIR}/${file}`, onOne, undefined, onOne)
  e = { albedo: load(`${key}.jpg`), normal: load(`${key}_n.jpg`), rough: load(`${key}_r.jpg`), ready: false, pending: [] }
  texDB.set(key, e)
  return e
}

function applyMaps(key: TexKey, mat: THREE.MeshStandardMaterial, rx: number, ry: number, o: MatOpts) {
  const e = getTex(key)
  const alb = e.albedo.clone()
  alb.wrapS = alb.wrapT = THREE.RepeatWrapping
  alb.repeat.set(rx, ry)
  alb.colorSpace = THREE.SRGBColorSpace
  alb.anisotropy = 4
  const nrm = e.normal.clone()
  nrm.wrapS = nrm.wrapT = THREE.RepeatWrapping
  nrm.repeat.set(rx, ry)
  nrm.anisotropy = 4
  const rgh = e.rough.clone()
  rgh.wrapS = rgh.wrapT = THREE.RepeatWrapping
  rgh.repeat.set(rx, ry)
  mat.map = alb
  mat.normalMap = nrm
  mat.roughnessMap = rgh
  const ns = o.normalScale ?? 1
  mat.normalScale = new THREE.Vector2(ns, ns)
  // roughness maps carry absolute values; material.roughness becomes the multiplier
  mat.roughness = o.roughnessMul ?? 1
  mat.color.set(0xffffff)
  mat.needsUpdate = true
}

function flush(key: TexKey) {
  const e = texDB.get(key)
  if (!e || e.ready) return
  // a failed download leaves image null -> never apply maps, keep fallback color
  e.ready = !!(e.albedo.image && e.normal.image && e.rough.image)
  const pend = e.pending
  e.pending = []
  if (!e.ready) return
  for (const p of pend) applyMaps(key, p.mat, p.rx, p.ry, p.o)
}

/** Material factory: textured (cached) or flat-color fallback. */
export function texMat(key: TexKey, rx = 1, ry = 1, o: MatOpts = {}): THREE.MeshStandardMaterial {
  const q = (v: number) => Math.max(0.25, Math.round(v * 4) / 4)
  const rrx = q(rx), rry = q(ry)
  const ck = `${key}|${rrx}|${rry}|${o.color ?? ''}|${o.metalness ?? ''}|${o.roughnessMul ?? ''}|${o.normalScale ?? ''}`
  const hit = matCache.get(ck)
  if (hit) return hit
  const f = FALLBACK[key]
  const mat = new THREE.MeshStandardMaterial({
    color: o.color ?? f.color,
    metalness: o.metalness ?? f.metalness,
    roughness: f.roughness,
  })
  const e = getTex(key)
  if (e.ready) applyMaps(key, mat, rrx, rry, o)
  else e.pending.push({ mat, rx: rrx, ry: rry, o })
  matCache.set(ck, mat)
  return mat
}

const matCache = new Map<string, THREE.MeshStandardMaterial>()

/** Kick off all texture downloads early so viewmodels never pop in mid-game. */
export function preloadWeaponTextures() {
  for (const k of Object.keys(FALLBACK) as TexKey[]) getTex(k)
}

// ---------------------------------------------------------------- geometry cache
const geoCache = new Map<string, THREE.BufferGeometry>()

export function box(w: number, h: number, d: number): THREE.BoxGeometry {
  const k = `b${w.toFixed(3)}:${h.toFixed(3)}:${d.toFixed(3)}`
  let g = geoCache.get(k) as THREE.BoxGeometry | undefined
  if (!g) { g = new THREE.BoxGeometry(w, h, d); geoCache.set(k, g) }
  return g
}

export function cyl(r: number, len: number, seg = 12): THREE.CylinderGeometry {
  const k = `c${r.toFixed(3)}:${len.toFixed(3)}:${seg}`
  let g = geoCache.get(k) as THREE.CylinderGeometry | undefined
  if (!g) { g = new THREE.CylinderGeometry(r, r, len, seg); geoCache.set(k, g) }
  return g
}

function repeatFor(geo: THREE.BufferGeometry, density: number): [number, number] {
  const p = (geo as THREE.BoxGeometry).parameters
  if (p && typeof p.width === 'number') {
    const dims = [p.width, p.height, p.depth].sort((a, b) => b - a)
    return [Math.max(0.35, dims[0] * density), Math.max(0.35, dims[1] * density)]
  }
  const c = (geo as THREE.CylinderGeometry).parameters
  if (c && typeof c.radiusTop === 'number') {
    const r = Math.max(c.radiusTop, c.radiusBottom)
    return [Math.max(0.35, Math.PI * 2 * r * density * 0.55), Math.max(0.35, c.height * density)]
  }
  return [1, 1]
}

/** Add a textured mesh part; auto texture-repeat from its geometry size. */
function P(parent: THREE.Object3D, geo: THREE.BufferGeometry, key: TexKey, o: MatOpts,
  x: number, y: number, z: number, rx = 0, ry = 0, rz = 0): THREE.Mesh {
  const f = FALLBACK[key]
  const [arx, ary] = repeatFor(geo, o.density ?? f.density)
  const mat = texMat(key, o.rx ?? arx, o.ry ?? ary, o)
  const m = new THREE.Mesh(geo, mat)
  m.position.set(x, y, z)
  m.rotation.set(rx, ry, rz)
  parent.add(m)
  return m
}

/** Flat basic material for lenses / LED dots / sights. */
function basic(color: number, parent: THREE.Object3D, geo: THREE.BufferGeometry,
  x: number, y: number, z: number, rx = 0, ry = 0, rz = 0): THREE.Mesh {
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }))
  m.position.set(x, y, z)
  m.rotation.set(rx, ry, rz)
  parent.add(m)
  return m
}

const q = (deg: number) => (deg * Math.PI) / 180

// ---------------------------------------------------------------- gloves
const CUFF: Record<TeamId, number> = { T: 0x9a7f4e, CT: 0x2c4a6e }

/**
 * Right hand + forearm wrapped around a grip point (local gun coords),
 * plus optional left support hand at a foregrip.
 * mirror=true flips everything across x — used by the dual berettas to
 * build a proper LEFT hand on the left-hand gun.
 */
// exported for weapongltf.ts (GLB knife viewmodel reuses the same glove rig)
export
function buildGloves(g: THREE.Object3D, team: TeamId,
  grip: { x: number; y: number; z: number; rx?: number },
  left?: { x: number; y: number; z: number; rx?: number }, mirror = false) {
  const s = mirror ? -1 : 1
  const rx = grip.rx ?? 0.25
  // palm wraps the grip
  P(g, box(0.055, 0.075, 0.105), 'glove_fabric', { color: 0x232527 }, grip.x + s * 0.012, grip.y - 0.01, grip.z + 0.01, rx)
  // fingers over the front strap
  for (let i = 0; i < 3; i++) {
    P(g, box(0.05, 0.017, 0.028), 'glove_fabric', { color: 0x1d1f21 },
      grip.x + s * 0.014, grip.y - 0.031 - i * 0.02, grip.z - 0.028 - i * 0.004, rx)
  }
  // thumb on the left/rear (mirrored: right/rear)
  P(g, box(0.017, 0.045, 0.022), 'glove_fabric', { color: 0x1d1f21 }, grip.x - s * 0.012, grip.y - 0.012, grip.z + 0.04, s * 0.1)
  // cuff band (team color)
  P(g, box(0.075, 0.075, 0.045), 'polymer_black', { color: CUFF[team], density: 2 },
    grip.x + s * 0.028, grip.y - 0.06, grip.z + 0.075, rx)
  // forearm running down-back toward the camera
  P(g, box(0.07, 0.072, 0.32), 'glove_fabric', {},
    grip.x + s * 0.052, grip.y - 0.145, grip.z + 0.235, 0.52, -s * 0.22, -s * 0.08)

  if (left) {
    const lrx = left.rx ?? 0.3
    P(g, box(0.055, 0.075, 0.1), 'glove_fabric', { color: 0x232527 }, left.x - s * 0.006, left.y - 0.015, left.z, lrx)
    P(g, box(0.05, 0.016, 0.03), 'glove_fabric', { color: 0x1d1f21 }, left.x - s * 0.004, left.y - 0.04, left.z + 0.005, lrx)
    P(g, box(0.075, 0.075, 0.045), 'polymer_black', { color: CUFF[team], density: 2 },
      left.x - s * 0.026, left.y - 0.07, left.z + 0.08, lrx)
    P(g, box(0.07, 0.072, 0.3), 'glove_fabric', {},
      left.x - s * 0.045, left.y - 0.16, left.z + 0.23, 0.5, s * 0.24, s * 0.08)
  }
}

// ---------------------------------------------------------------- AK-47
function buildAK(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver + dust cover
  P(g, box(0.058, 0.07, 0.30), 'steel_blued', {}, 0, 0.005, -0.15)
  P(g, box(0.054, 0.026, 0.26), 'steel_blued', { roughnessMul: 0.9 }, 0, 0.045, -0.16)
  // rear sight block + front sight
  P(g, box(0.05, 0.02, 0.03), 'steel_blued', {}, 0, 0.058, -0.30)
  P(g, box(0.012, 0.045, 0.012), 'steel_blued', {}, 0, 0.05, -0.62)
  P(g, box(0.004, 0.03, 0.012), 'steel_blued', {}, 0.014, 0.05, -0.62)
  P(g, box(0.004, 0.03, 0.012), 'steel_blued', {}, -0.014, 0.05, -0.62)
  // gas system
  P(g, box(0.024, 0.03, 0.03), 'steel_blued', {}, 0, 0.033, -0.50)
  P(g, cyl(0.009, 0.24), 'steel_blued', {}, 0, 0.045, -0.42, q(90))
  // barrel + slant brake
  P(g, cyl(0.010, 0.40), 'steel_blued', {}, 0, 0.01, -0.55, q(90))
  P(g, cyl(0.0135, 0.035), 'steel_blued', {}, 0, 0.01, -0.755, q(90))
  P(g, box(0.013, 0.024, 0.03), 'steel_blued', {}, 0.002, 0.004, -0.768, 0, 0, -0.35)
  // wood furniture
  P(g, box(0.052, 0.042, 0.16), 'wood_laminate', {}, 0, 0.0, -0.38)
  P(g, box(0.046, 0.028, 0.13), 'wood_laminate', { roughnessMul: 0.9 }, 0, 0.031, -0.36)
  P(g, box(0.04, 0.062, 0.24), 'wood_laminate', {}, 0, -0.018, 0.15, 0.1)
  P(g, box(0.043, 0.09, 0.012), 'steel_blued', {}, 0, -0.035, 0.272)
  // pistol grip + trigger guard
  P(g, box(0.036, 0.09, 0.05), 'wood_laminate', { color: 0x7a4a20 }, 0, -0.062, 0.022, 0.3)
  P(g, box(0.03, 0.005, 0.052), 'steel_blued', {}, 0, -0.045, -0.02)
  // charging handle
  P(g, box(0.024, 0.01, 0.018), 'steel_blued', {}, 0.038, 0.032, -0.25)
  // curved magazine (progressive pitch segments)
  const mag = new THREE.Group()
  g.add(mag)
  for (let i = 0; i < 4; i++) {
    P(mag, box(0.047, 0.05, 0.078), 'metal_dark', { roughnessMul: 0.8 },
      0, -0.062 - i * 0.047, -0.135 - i * 0.021, -0.24 * i)
  }
  P(mag, box(0.05, 0.014, 0.085), 'metal_dark', {}, 0, -0.232, -0.182, -0.75)
  buildGloves(g, team, { x: 0, y: -0.055, z: 0.03, rx: 0.3 }, { x: 0, y: -0.03, z: -0.36, rx: 0.25 })
  return { group: g, tip: new THREE.Vector3(0, 0.01, -0.78), mag, eject: new THREE.Vector3(0.034, 0.02, -0.22) }
}

// ---------------------------------------------------------------- M4A4
function buildM4(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receivers
  P(g, box(0.05, 0.05, 0.24), 'polymer_black', { color: 0x26292c }, 0, 0.022, -0.13)
  P(g, box(0.048, 0.06, 0.12), 'polymer_black', { color: 0x222527 }, 0, -0.03, -0.09)
  // flat-top rail with notch slots
  P(g, box(0.03, 0.01, 0.27), 'polymer_black', { color: 0x2a2d30 }, 0, 0.052, -0.13)
  for (let i = 0; i < 9; i++) {
    P(g, box(0.032, 0.006, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.053, -0.26 + i * 0.03)
  }
  // barrel + birdcage
  P(g, cyl(0.009, 0.28), 'steel_blued', {}, 0, 0.014, -0.41, q(90))
  P(g, cyl(0.0125, 0.05), 'steel_blued', {}, 0, 0.014, -0.575, q(90))
  P(g, box(0.004, 0.01, 0.035), 'metal_dark', { color: 0x101214 }, 0.012, 0.014, -0.575)
  P(g, box(0.004, 0.01, 0.035), 'metal_dark', { color: 0x101214 }, -0.012, 0.014, -0.575)
  // front sight tower (triangle)
  P(g, box(0.012, 0.05, 0.012), 'polymer_black', { color: 0x26292c }, 0.012, 0.048, -0.28, 0, 0, 0.3)
  P(g, box(0.012, 0.05, 0.012), 'polymer_black', { color: 0x26292c }, -0.012, 0.048, -0.28, 0, 0, -0.3)
  P(g, box(0.006, 0.018, 0.006), 'metal_dark', {}, 0, 0.082, -0.28)
  // railed handguard
  P(g, box(0.052, 0.05, 0.22), 'polymer_black', { color: 0x25282a }, 0, 0.014, -0.33)
  for (let i = 0; i < 5; i++) {
    P(g, box(0.054, 0.006, 0.014), 'metal_dark', { color: 0x101214 }, 0, 0.043, -0.26 - i * 0.035)
  }
  P(g, box(0.006, 0.03, 0.2), 'metal_dark', { color: 0x16181a }, 0.028, 0.006, -0.33)
  P(g, box(0.006, 0.03, 0.2), 'metal_dark', { color: 0x16181a }, -0.028, 0.006, -0.33)
  // charging handle + rear sight
  P(g, box(0.03, 0.012, 0.032), 'polymer_black', { color: 0x26292c }, 0, 0.05, 0.0)
  P(g, box(0.03, 0.014, 0.02), 'polymer_black', { color: 0x26292c }, 0, 0.062, 0.005)
  // magazine
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.038, 0.125, 0.058), 'polymer_black', { color: 0x1f2224 }, 0, -0.108, -0.065, -0.07)
  P(mag, box(0.042, 0.014, 0.064), 'polymer_black', { color: 0x191c1e }, 0, -0.172, -0.07, -0.07)
  // stock: tube + butt
  P(g, cyl(0.016, 0.15), 'polymer_black', { color: 0x2a2d30 }, 0, 0.028, 0.115, q(90))
  P(g, box(0.04, 0.09, 0.1), 'polymer_black', { color: 0x26292c }, 0, 0.0, 0.22)
  P(g, box(0.042, 0.095, 0.015), 'polymer_black', { color: 0x16181a }, 0, 0.0, 0.272)
  P(g, box(0.036, 0.02, 0.08), 'polymer_black', { color: 0x26292c }, 0, 0.055, 0.18, -0.15)
  // trigger
  P(g, box(0.006, 0.028, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.035, -0.015, 0.15)
  buildGloves(g, team, { x: 0, y: -0.05, z: 0.03, rx: 0.28 }, { x: 0, y: -0.02, z: -0.33, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.014, -0.62), mag, eject: new THREE.Vector3(0.03, 0.035, -0.15) }
}

// ---------------------------------------------------------------- AWP
function buildAWP(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver
  P(g, box(0.05, 0.06, 0.28), 'steel_blued', {}, 0, 0.01, -0.12)
  // barrel + muzzle brake
  P(g, cyl(0.012, 0.52), 'steel_blued', {}, 0, 0.02, -0.52, q(90))
  P(g, cyl(0.017, 0.062), 'steel_blued', {}, 0, 0.02, -0.79, q(90))
  for (let i = 0; i < 3; i++) {
    P(g, box(0.005, 0.012, 0.03), 'metal_dark', { color: 0x101214 }, 0.017, 0.02, -0.76 - i * 0.02)
    P(g, box(0.005, 0.012, 0.03), 'metal_dark', { color: 0x101214 }, -0.017, 0.02, -0.76 - i * 0.02)
  }
  // scope: tube + bells + lens + turrets + rings
  P(g, cyl(0.021, 0.26, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.088, -0.16, q(90))
  P(g, cyl(0.03, 0.055, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.088, -0.30, q(90))
  P(g, cyl(0.025, 0.045, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.088, -0.015, q(90))
  basic(0x24384a, g, cyl(0.027, 0.003, 16), 0, 0.088, -0.326, q(90))       // objective lens
  basic(0x2c3a2a, g, cyl(0.022, 0.003, 16), 0, 0.088, 0.009, q(90))        // ocular lens
  P(g, cyl(0.009, 0.018, 12), 'metal_dark', {}, 0, 0.118, -0.16)           // elevation turret
  P(g, cyl(0.009, 0.018, 12), 'metal_dark', {}, 0.03, 0.088, -0.16, 0, 0, q(90)) // windage turret
  P(g, box(0.02, 0.045, 0.026), 'metal_dark', {}, 0, 0.055, -0.07)         // front mount
  P(g, box(0.02, 0.045, 0.026), 'metal_dark', {}, 0, 0.055, -0.24)         // rear mount
  // chassis / stock in olive enamel
  P(g, box(0.052, 0.05, 0.17), 'enamel_od', {}, 0, 0.0, -0.28)             // forend
  P(g, box(0.05, 0.085, 0.28), 'enamel_od', {}, 0, -0.005, 0.1)            // butt frame
  P(g, box(0.045, 0.1, 0.06), 'enamel_od', {}, 0, -0.065, 0.03, 0.18)      // grip
  P(g, box(0.045, 0.03, 0.13), 'enamel_od', {}, 0, 0.048, 0.05)            // cheek riser
  P(g, box(0.052, 0.11, 0.02), 'polymer_black', { color: 0x16181a }, 0, -0.01, 0.245) // butt pad
  // magazine box
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.04, 0.075, 0.09), 'polymer_black', { color: 0x1f2224 }, 0, -0.062, -0.10, -0.08)
  P(mag, box(0.044, 0.012, 0.095), 'polymer_black', { color: 0x16181a }, 0, -0.102, -0.104, -0.08)
  // bolt assembly (animates: lift, pull, push, drop)
  const bolt = new THREE.Group()
  g.add(bolt)
  P(bolt, cyl(0.007, 0.075, 10), 'steel_blued', { roughnessMul: 0.5 }, 0.028, 0.048, 0.02, q(90))
  P(bolt, cyl(0.005, 0.032, 8), 'steel_blued', {}, 0.052, 0.028, 0.02, 0, 0, q(60))
  P(bolt, new THREE.SphereGeometry(0.009, 10, 8), 'steel_blued', { roughnessMul: 0.5 }, 0.066, 0.011, 0.02)
  buildGloves(g, team, { x: 0, y: -0.055, z: 0.05, rx: 0.3 }, { x: 0, y: -0.03, z: -0.3, rx: 0.25 })
  return { group: g, tip: new THREE.Vector3(0, 0.02, -0.84), mag, bolt, eject: new THREE.Vector3(0.034, 0.035, -0.1), muzzleLen: 0.86 }
}

// ---------------------------------------------------------------- Phase 5 rifles
// Parametric rifle family (plan 5.5): the ak/m4 builders generalize —
// conventional layout (galil/sg553/m4a1s) + bullpup layout (famas/aug).
// Sniper family (ssg08/scar20/g3sg1) lives below with the AWP glass pattern.

interface RifleSpec {
  layout: 'conv' | 'bullpup'
  bodyLen: number; bodyH: number; bodyW: number; bodyCol: number
  handLen: number; handCol: number     // handguard (conv) / front shell taper
  barrelR: number; barrelLen: number; muzzleZ: number
  magLen: number; magSegs: number      // curved-mag segment count
  stockCol: number
  rail?: boolean                       // flat-top rail + notches
  suppressor?: boolean                 // m4a1s integral can
  optic?: 'small' | 'scope'            // sg553 compact optic / aug forward tube
  carryHandle?: boolean                // famas
  magBehindGrip?: boolean              // aug bullpup mag position
}

const RIFLES: Record<'galil' | 'famas' | 'sg553' | 'aug' | 'm4a1s', RifleSpec> = {
  // T budget rifle: polymer AK-ish, tall front sight, long 35-rd curved mag
  galil: { layout: 'conv', bodyLen: 0.26, bodyH: 0.07, bodyW: 0.05, bodyCol: 0x25282a, handLen: 0.15, handCol: 0x25282a, barrelR: 0.010, barrelLen: 0.13, muzzleZ: -0.50, magLen: 0.20, magSegs: 4, stockCol: 0x25282a },
  // CT bullpup: carry handle, mag ahead of the grip, 3-round burst
  famas: { layout: 'bullpup', bodyLen: 0.34, bodyH: 0.06, bodyW: 0.048, bodyCol: 0x2a2d30, handLen: 0.16, handCol: 0x25282a, barrelR: 0.009, barrelLen: 0.08, muzzleZ: -0.42, magLen: 0.13, magSegs: 2, stockCol: 0x1f2224, carryHandle: true },
  // T scoped: compact optic, 100% armor pen, skeleton stock
  sg553: { layout: 'conv', bodyLen: 0.24, bodyH: 0.06, bodyW: 0.05, bodyCol: 0x232629, handLen: 0.16, handCol: 0x25282a, barrelR: 0.010, barrelLen: 0.12, muzzleZ: -0.48, magLen: 0.17, magSegs: 3, stockCol: 0x25282a, optic: 'small' },
  // CT bullpup: integrated forward scope, mag behind the grip
  aug: { layout: 'bullpup', bodyLen: 0.36, bodyH: 0.075, bodyW: 0.048, bodyCol: 0x2d7d4f, handLen: 0.18, handCol: 0x2d7d4f, barrelR: 0.009, barrelLen: 0.09, muzzleZ: -0.44, magLen: 0.12, magSegs: 2, stockCol: 0x2d7d4f, optic: 'scope', magBehindGrip: true },
  // CT silenced M4: rail + integral suppressor + short 20-rd mag
  m4a1s: { layout: 'conv', bodyLen: 0.24, bodyH: 0.05, bodyW: 0.05, bodyCol: 0x26292c, handLen: 0.22, handCol: 0x25282a, barrelR: 0.009, barrelLen: 0.10, muzzleZ: -0.62, magLen: 0.11, magSegs: 2, stockCol: 0x26292c, rail: true, suppressor: true },
}

function buildRifle(id: keyof typeof RIFLES, team: TeamId): ViewModel {
  const s = RIFLES[id]
  const g = new THREE.Group()
  const bodyZ = -s.bodyLen / 2 + 0.03
  // receiver
  P(g, box(s.bodyW, s.bodyH, s.bodyLen), 'polymer_black', { color: s.bodyCol }, 0, 0.02, bodyZ)
  if (s.rail) {
    P(g, box(s.bodyW - 0.014, 0.01, s.bodyLen * 0.95), 'polymer_black', { color: 0x2a2d30 }, 0, 0.02 + s.bodyH / 2 + 0.005, bodyZ - 0.01)
    for (let i = 0; i < 7; i++) {
      P(g, box(s.bodyW - 0.012, 0.006, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.02 + s.bodyH / 2 + 0.007, bodyZ + 0.03 - i * (s.bodyLen / 7.5))
    }
  }
  if (s.carryHandle) {
    // famas: full-length carry handle over the receiver
    P(g, box(0.02, 0.03, s.bodyLen * 0.8), 'polymer_black', { color: s.bodyCol }, 0, 0.02 + s.bodyH / 2 + 0.015, bodyZ)
    P(g, box(0.014, 0.018, 0.03), 'metal_dark', { color: 0x16181a }, 0, 0.062, bodyZ + s.bodyLen * 0.78)
    P(g, box(0.014, 0.018, 0.03), 'metal_dark', { color: 0x16181a }, 0, 0.062, bodyZ - s.bodyLen * 0.28)
  }
  if (s.optic === 'small') {
    // sg553: compact tube optic + dark lens
    P(g, cyl(0.016, 0.08, 12), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.075, bodyZ + 0.02, q(90))
    basic(0x24384a, g, cyl(0.013, 0.003, 12), 0, 0.075, bodyZ - 0.021, q(90))
    P(g, box(0.018, 0.03, 0.02), 'metal_dark', {}, 0, 0.058, bodyZ + 0.02)
  }
  if (s.optic === 'scope') {
    // aug: integrated forward scope above the handguard half
    P(g, cyl(0.02, 0.16, 14), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.085, bodyZ - 0.04, q(90))
    P(g, cyl(0.026, 0.04, 14), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.085, bodyZ - 0.125, q(90))
    basic(0x24384a, g, cyl(0.023, 0.003, 14), 0, 0.085, bodyZ - 0.147, q(90))
    P(g, box(0.02, 0.035, 0.022), 'metal_dark', {}, 0, 0.062, bodyZ - 0.02)
  }
  // barrel / suppressor
  if (s.suppressor) {
    // m4a1s: short barrel stub + fat integral can with vent rings
    P(g, cyl(s.barrelR, 0.05), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.02, s.muzzleZ + 0.17, q(90))
    P(g, cyl(0.0165, 0.15, 14), 'metal_dark', { roughnessMul: 0.75 }, 0, 0.02, s.muzzleZ + 0.075, q(90))
    for (let i = 0; i < 3; i++) {
      P(g, cyl(0.0175, 0.008, 14), 'metal_dark', { color: 0x16181a }, 0, 0.02, s.muzzleZ + 0.03 + i * 0.05, q(90))
    }
  } else {
    P(g, cyl(s.barrelR, s.barrelLen), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.02, s.muzzleZ + s.barrelLen / 2, q(90))
    // tall front sight (galil) / slim A2 post (others)
    if (id === 'galil') {
      P(g, box(0.006, 0.045, 0.006), 'metal_dark', { color: 0x16181a }, 0, 0.05, s.muzzleZ + 0.03)
      P(g, box(0.02, 0.008, 0.014), 'metal_dark', { color: 0x16181a }, 0, 0.072, s.muzzleZ + 0.03)
    } else {
      P(g, box(0.005, 0.026, 0.006), 'metal_dark', { color: 0x16181a }, 0, 0.045, s.muzzleZ + 0.035)
    }
  }
  // charging handle
  P(g, box(0.02, 0.009, 0.016), 'metal_dark', { color: 0x101214 }, s.bodyW / 2 + 0.006, 0.03, bodyZ + 0.03)
  // handguard / front shell
  if (s.layout === 'conv') {
    P(g, box(s.bodyW - 0.004, s.bodyH - 0.012, s.handLen), 'polymer_black', { color: s.handCol }, 0, 0.02, bodyZ - s.bodyLen / 2 - s.handLen / 2 + 0.02)
    if (s.rail) {
      for (let i = 0; i < 5; i++) {
        P(g, box(s.bodyW, 0.006, 0.014), 'metal_dark', { color: 0x101214 }, 0, 0.02 + (s.bodyH - 0.012) / 2 + 0.006, bodyZ - s.bodyLen / 2 - i * 0.035 + 0.01)
      }
    }
  } else {
    // bullpup: front shell taper + foregrip stub
    P(g, box(s.bodyW - 0.006, s.bodyH - 0.018, s.handLen), 'polymer_black', { color: s.handCol }, 0, 0.014, bodyZ - s.bodyLen / 2 - s.handLen / 2 + 0.02)
    P(g, box(0.028, 0.055, 0.05), 'polymer_black', { color: s.stockCol }, 0, -0.03, bodyZ - s.bodyLen / 2 - 0.06, -0.3)
  }
  // trigger + grip
  P(g, box(0.005, 0.028, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.028, s.layout === 'bullpup' ? -0.06 : -0.015, 0.15)
  P(g, box(0.034, 0.095, 0.05), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.07, s.layout === 'bullpup' ? -0.03 : 0.015, s.layout === 'bullpup' ? 0.28 : 0.24)
  // magazine (curved segments, count scaled to capacity)
  const mag = new THREE.Group()
  g.add(mag)
  const magZ = s.magBehindGrip ? bodyZ + 0.08 : (s.layout === 'bullpup' ? bodyZ - 0.02 : -0.09)
  const segH = s.magLen / s.magSegs
  for (let i = 0; i < s.magSegs; i++) {
    P(mag, box(0.036, segH, 0.055), 'metal_dark', { color: 0x1b1e21 },
      0, -0.05 - i * segH, magZ - i * 0.016, -0.22 * i)
  }
  P(mag, box(0.04, 0.012, 0.062), 'metal_dark', { color: 0x141618 }, 0, -0.05 - s.magLen - 0.004, magZ - s.magSegs * 0.016, -0.35)
  // stock
  if (s.layout === 'conv') {
    if (id === 'sg553') {
      // skeleton: twin bars + butt
      P(g, cyl(0.008, 0.16, 8), 'polymer_black', { color: s.stockCol }, 0.01, 0.026, 0.13, q(90))
      P(g, box(0.03, 0.05, 0.09), 'polymer_black', { color: s.stockCol }, 0, 0.0, 0.19)
      P(g, box(0.033, 0.08, 0.014), 'polymer_black', { color: 0x16181a }, 0, -0.005, 0.235)
    } else {
      P(g, box(0.04, 0.062, 0.18), 'polymer_black', { color: s.stockCol }, 0, 0.006, 0.14)
      P(g, box(0.043, 0.085, 0.015), 'polymer_black', { color: 0x16181a }, 0, -0.002, 0.238)
    }
  } else {
    // bullpup: rear shell is the stock — cheek riser + butt pad
    P(g, box(s.bodyW - 0.004, s.bodyH - 0.008, 0.12), 'polymer_black', { color: s.stockCol }, 0, 0.012, bodyZ + s.bodyLen / 2 + 0.05)
    P(g, box(s.bodyW, 0.08, 0.014), 'polymer_black', { color: 0x16181a }, 0, -0.002, bodyZ + s.bodyLen / 2 + 0.115)
  }
  buildGloves(g, team,
    { x: 0, y: -0.065, z: s.layout === 'bullpup' ? -0.015 : 0.03, rx: 0.3 },
    { x: 0, y: -0.03, z: s.layout === 'bullpup' ? bodyZ - s.bodyLen / 2 - 0.05 : bodyZ - s.bodyLen / 2 - s.handLen / 2, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.02, s.muzzleZ), mag, eject: new THREE.Vector3(s.bodyW / 2 + 0.004, 0.04, bodyZ + 0.04) }
}

// ---------------------------------------------------------------- Phase 5 snipers
// Parametric sniper family — reuses the AWP's glass/turret pattern (plan 5.5).
// ssg08 is bolt-action (bolt group animates); scar20/g3sg1 are semi-auto
// (no bolt cycle anim — shells eject each shot).

interface SniperSpec {
  bodyLen: number; bodyH: number; bodyW: number; bodyCol: number
  barrelR: number; barrelLen: number; muzzleZ: number
  scopeR: number; scopeLen: number; scopeZ: number
  stockCol: number; woodGrip?: boolean
  magH: number
  bolt: boolean
  brakeR: number
}

const SNIPERS: Record<'ssg08' | 'scar20' | 'g3sg1', SniperSpec> = {
  // light scout: slim everything, fast handling
  ssg08: { bodyLen: 0.24, bodyH: 0.05, bodyW: 0.045, bodyCol: 0x232629, barrelR: 0.010, barrelLen: 0.36, muzzleZ: -0.66, scopeR: 0.017, scopeLen: 0.22, scopeZ: -0.17, stockCol: 0x1f2224, magH: 0.06, bolt: true, brakeR: 0.013 },
  // CT auto-sniper: chunky black body, big glass
  scar20: { bodyLen: 0.30, bodyH: 0.07, bodyW: 0.055, bodyCol: 0x232629, barrelR: 0.011, barrelLen: 0.34, muzzleZ: -0.66, scopeR: 0.021, scopeLen: 0.26, scopeZ: -0.20, stockCol: 0x25282a, magH: 0.08, bolt: false, brakeR: 0.015 },
  // T auto-sniper: olive receiver + wood grip accents
  g3sg1: { bodyLen: 0.30, bodyH: 0.07, bodyW: 0.052, bodyCol: 0x2d3326, barrelR: 0.011, barrelLen: 0.38, muzzleZ: -0.70, scopeR: 0.021, scopeLen: 0.26, scopeZ: -0.20, stockCol: 0x2d3326, woodGrip: true, magH: 0.08, bolt: false, brakeR: 0.015 },
}

function buildSniper(id: keyof typeof SNIPERS, team: TeamId): ViewModel {
  const s = SNIPERS[id]
  const g = new THREE.Group()
  const bodyZ = -s.bodyLen / 2 + 0.05
  // receiver
  P(g, box(s.bodyW, s.bodyH, s.bodyLen), 'metal_dark', { color: s.bodyCol }, 0, 0.015, bodyZ)
  // barrel + muzzle brake
  P(g, cyl(s.barrelR, s.barrelLen), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.022, s.muzzleZ + s.barrelLen / 2, q(90))
  P(g, cyl(s.brakeR, 0.05, 12), 'metal_dark', { color: 0x101214 }, 0, 0.022, s.muzzleZ + 0.025, q(90))
  // scope: tube + bells + lenses + turrets + rings (AWP glass pattern)
  const sy = 0.015 + s.bodyH / 2 + s.scopeR + 0.006
  P(g, cyl(s.scopeR, s.scopeLen, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, sy, s.scopeZ, q(90))
  P(g, cyl(s.scopeR + 0.009, 0.05, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, sy, s.scopeZ - s.scopeLen / 2 - 0.02, q(90))
  P(g, cyl(s.scopeR + 0.004, 0.04, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, sy, s.scopeZ + s.scopeLen / 2 + 0.015, q(90))
  basic(0x24384a, g, cyl(s.scopeR + 0.007, 0.003, 16), 0, sy, s.scopeZ - s.scopeLen / 2 - 0.046, q(90))
  basic(0x2c3a2a, g, cyl(s.scopeR + 0.002, 0.003, 16), 0, sy, s.scopeZ + s.scopeLen / 2 + 0.036, q(90))
  P(g, cyl(0.008, 0.016, 12), 'metal_dark', {}, 0, sy + s.scopeR + 0.008, s.scopeZ)
  P(g, cyl(0.008, 0.016, 12), 'metal_dark', {}, s.scopeR + 0.008, sy, s.scopeZ, 0, 0, q(90))
  P(g, box(0.018, 0.03, 0.022), 'metal_dark', {}, 0, 0.015 + s.bodyH / 2 + 0.014, s.scopeZ + 0.06)
  P(g, box(0.018, 0.03, 0.022), 'metal_dark', {}, 0, 0.015 + s.bodyH / 2 + 0.014, s.scopeZ - 0.07)
  // stock (skeleton with cheek riser) + butt pad
  P(g, box(s.bodyW - 0.006, s.bodyH - 0.008, 0.20), 'metal_dark', { color: s.stockCol }, 0, 0.008, bodyZ + s.bodyLen / 2 + 0.10)
  P(g, box(s.bodyW, 0.02, 0.12), 'polymer_black', { color: s.stockCol }, 0, 0.038, bodyZ + s.bodyLen / 2 + 0.08)
  P(g, box(s.bodyW, 0.09, 0.016), 'polymer_black', { color: 0x16181a }, 0, -0.005, bodyZ + s.bodyLen / 2 + 0.205)
  // grip + trigger
  P(g, box(0.034, 0.09, 0.05), 'polymer_black', { density: 9, color: s.woodGrip ? 0x6b4520 : 0x1f2224 }, 0, -0.06, 0.03, 0.26)
  P(g, box(0.005, 0.026, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.026, -0.005, 0.15)
  // magazine box
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.036, s.magH, 0.085), 'metal_dark', { color: 0x1b1e21 }, 0, -0.04 - s.magH / 2, -0.06, -0.06)
  P(mag, box(0.04, 0.012, 0.09), 'metal_dark', { color: 0x141618 }, 0, -0.04 - s.magH + 0.006, -0.065, -0.06)
  // bolt assembly (bolt-action only — animates on fire)
  let bolt: THREE.Group | undefined
  if (s.bolt) {
    bolt = new THREE.Group()
    g.add(bolt)
    P(bolt, cyl(0.007, 0.075, 10), 'steel_blued', { roughnessMul: 0.5 }, 0.028, 0.04, 0.03, q(90))
    P(bolt, cyl(0.005, 0.032, 8), 'steel_blued', {}, 0.052, 0.02, 0.03, 0, 0, q(60))
    P(bolt, new THREE.SphereGeometry(0.009, 10, 8), 'steel_blued', { roughnessMul: 0.5 }, 0.066, 0.003, 0.03)
  }
  buildGloves(g, team, { x: 0, y: -0.06, z: 0.04, rx: 0.3 }, { x: 0, y: -0.03, z: bodyZ - s.bodyLen / 2 - 0.06, rx: 0.28 })
  return {
    group: g, tip: new THREE.Vector3(0, 0.022, s.muzzleZ), mag, bolt,
    eject: new THREE.Vector3(s.bodyW / 2 + 0.004, 0.04, bodyZ + 0.05),
    muzzleLen: -s.muzzleZ + 0.02,
  }
}

// ---------------------------------------------------------------- Phase 6 shotguns
// Parametric shotgun family (plan 6.3). Shared bones: receiver + barrel over
// an under-barrel shell TUBE (the `mag` group, userData.fixed — shells load
// through the port, the tube never drops) + pump fore-end (the `pump` group,
// racks after every shot on the pump-action guns). Per-model mold breaks:
//  nova     classic pump: slim polymer, 8-shell tube, full stock, front bead
//  xm1014   auto: chunky receiver, heat-shield ribs, side charging handle —
//           gas-operated, so NO cycling pump (static handguard)
//  mag7     compact CAWS: 5-rd BOX magazine below the action (the only
//           shotgun mag that actually drops on reload), short thick barrel
//  sawedoff cut-down: wood furniture, exposed hammer, pistol grip, no stock

interface ShotgunSpec {
  bodyLen: number; bodyH: number; bodyW: number; bodyCol: number
  barrelR: number; barrelLen: number; muzzleZ: number
  tubeR: number; tubeLen: number          // under-barrel shell tube (0 = box-mag gun)
  pumpLen: number                         // 0 = no cycling fore-end (xm1014)
  stock: 'full' | 'compact' | 'none'
  wood?: boolean
  bead?: boolean
  heatShield?: boolean
  chargingHandle?: boolean
  hammer?: boolean
  boxMag?: { w: number; h: number; d: number }
}

const SHOTGUNS: Record<'nova' | 'xm1014' | 'mag7' | 'sawedoff', ShotgunSpec> = {
  nova: {
    bodyLen: 0.22, bodyH: 0.055, bodyW: 0.045, bodyCol: 0x232629,
    barrelR: 0.011, barrelLen: 0.40, muzzleZ: -0.62,
    tubeR: 0.014, tubeLen: 0.34, pumpLen: 0.11, stock: 'full', bead: true,
  },
  xm1014: {
    bodyLen: 0.27, bodyH: 0.065, bodyW: 0.052, bodyCol: 0x2a2d30,
    barrelR: 0.012, barrelLen: 0.34, muzzleZ: -0.58,
    tubeR: 0.016, tubeLen: 0.30, pumpLen: 0, stock: 'full',
    heatShield: true, chargingHandle: true,
  },
  mag7: {
    bodyLen: 0.24, bodyH: 0.07, bodyW: 0.052, bodyCol: 0x2a2d30,
    barrelR: 0.013, barrelLen: 0.20, muzzleZ: -0.40,
    tubeR: 0, tubeLen: 0, pumpLen: 0.09, stock: 'compact',
    boxMag: { w: 0.04, h: 0.09, d: 0.055 },
  },
  sawedoff: {
    bodyLen: 0.17, bodyH: 0.05, bodyW: 0.042, bodyCol: 0x3a2f26,
    barrelR: 0.011, barrelLen: 0.24, muzzleZ: -0.36,
    tubeR: 0.013, tubeLen: 0.19, pumpLen: 0.075, stock: 'none',
    wood: true, bead: true, hammer: true,
  },
}

function buildShotgun(id: keyof typeof SHOTGUNS, team: TeamId): ViewModel {
  const s = SHOTGUNS[id]
  const g = new THREE.Group()
  const bodyZ = -s.bodyLen / 2 + 0.03
  const boreY = 0.02
  const furn: TexKey = s.wood ? 'wood_laminate' : 'polymer_black'
  const furnCol = s.wood ? 0x6e4a26 : s.bodyCol

  // receiver
  P(g, box(s.bodyW, s.bodyH, s.bodyLen), s.wood ? 'metal_dark' : 'polymer_black',
    { color: s.bodyCol }, 0, boreY, bodyZ)
  if (s.hammer) {
    // sawed-off: exposed spur hammer behind the receiver
    P(g, box(0.012, 0.02, 0.012), 'steel_blued', { roughnessMul: 0.5 }, 0, boreY + s.bodyH / 2 + 0.008, bodyZ + s.bodyLen / 2 + 0.004, -0.5)
  }

  // barrel
  P(g, cyl(s.barrelR, s.barrelLen), 'steel_blued', { roughnessMul: 0.6 }, 0, boreY, s.muzzleZ + s.barrelLen / 2, q(90))
  if (s.heatShield) {
    // xm1014: ribbed heat shield over the barrel
    for (let i = 0; i < 5; i++) {
      P(g, cyl(s.barrelR + 0.004, 0.01, 10), 'metal_dark', { color: 0x1b1e21 }, 0, boreY, s.muzzleZ + 0.08 + i * 0.055, q(90))
    }
  }
  if (s.bead) {
    basic(0xf4f4f4, g, new THREE.SphereGeometry(0.004, 8, 6), 0, boreY + s.barrelR + 0.004, s.muzzleZ + 0.008)
  }
  if (id === 'mag7') {
    // MAG-7: chunky front sight block + short top rail handle
    P(g, box(0.014, 0.03, 0.02), 'metal_dark', { color: 0x16181a }, 0, boreY + s.bodyH / 2 + 0.006, s.muzzleZ + 0.05)
    P(g, box(0.02, 0.014, 0.1), 'metal_dark', { color: 0x1b1e21 }, 0, boreY + s.bodyH / 2 + 0.01, bodyZ - 0.02)
  }

  // magazine group — under-barrel shell TUBE (fixed) or mag7's BOX mag
  const mag = new THREE.Group()
  g.add(mag)
  if (s.boxMag) {
    // mag7: 5-rd box below the action, drops like an SMG mag on reload
    const bm = P(mag, box(s.boxMag.w, s.boxMag.h, s.boxMag.d), 'metal_dark', { color: 0x1b1e21 },
      0, -0.06, bodyZ - 0.04, -0.12)
    bm.userData.homeY = -0.06
    P(mag, box(s.boxMag.w + 0.004, 0.01, s.boxMag.d + 0.004), 'metal_dark', { color: 0x141618 }, 0, -0.06 - s.boxMag.h / 2 - 0.004, bodyZ - 0.04)
  } else {
    // shell tube under the barrel, slightly shorter than the barrel
    const tubeY = boreY - s.barrelR - s.tubeR - 0.004
    P(mag, cyl(s.tubeR, s.tubeLen, 12), 'metal_dark', { color: s.wood ? 0x2b2f33 : s.bodyCol },
      0, tubeY, s.muzzleZ + s.tubeLen / 2 + 0.05, q(90))
    mag.userData.fixed = true
    mag.userData.homeY = tubeY
    // tube end cap
    P(mag, cyl(s.tubeR + 0.002, 0.012, 12), 'metal_dark', { color: 0x141618 }, 0, tubeY, s.muzzleZ + s.tubeLen + 0.05, q(90))
  }

  // pump fore-end (cycling group) or static handguard (xm1014)
  let pump: THREE.Group | undefined
  const handY = s.boxMag ? boreY - 0.03 : boreY - s.barrelR - s.tubeR - 0.004 - 0.012
  if (s.pumpLen > 0) {
    pump = new THREE.Group()
    g.add(pump)
    const pz = s.muzzleZ + s.tubeLen - s.pumpLen / 2 - 0.02
    const pumpMesh = P(pump, box(s.tubeR * 2 + 0.02, s.tubeR * 2 + 0.014, s.pumpLen), furn,
      { color: furnCol }, 0, handY + 0.012, pz)
    pumpMesh.userData.homeZ = pz
    // pump grooves
    for (let i = 0; i < 3; i++) {
      P(pump, box(s.tubeR * 2 + 0.021, 0.004, s.pumpLen * 0.14), 'metal_dark', { color: 0x16181a },
        0, handY + 0.012 - s.tubeR - 0.004 + i * 0.008, pz - s.pumpLen * 0.3 + i * s.pumpLen * 0.3)
    }
    pump.userData.homeZ = pz
  } else {
    // xm1014: full-length vented handguard (static)
    P(g, box(s.bodyW - 0.004, 0.045, 0.22), 'polymer_black', { color: 0x25282a }, 0, boreY - 0.03, bodyZ - s.bodyLen / 2 - 0.1)
  }
  if (s.chargingHandle) {
    P(g, box(0.02, 0.009, 0.016), 'metal_dark', { color: 0x101214 }, s.bodyW / 2 + 0.006, boreY + 0.012, bodyZ + 0.04)
  }

  // trigger + grip
  P(g, box(0.005, 0.028, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.028, s.stock === 'none' ? bodyZ + 0.02 : -0.01, 0.15)
  const gripR = s.stock === 'none' ? 0.5 : 0.24
  P(g, box(0.034, 0.09, 0.05), furn, { color: s.wood ? 0x5a3d1e : 0x1f2224 },
    0, s.stock === 'none' ? -0.055 : -0.07, s.stock === 'none' ? bodyZ + 0.055 : 0.02, gripR)

  // stock / compact tail
  if (s.stock === 'full') {
    P(g, box(0.04, 0.06, 0.16), furn, { color: furnCol }, 0, 0.008, bodyZ + s.bodyLen / 2 + 0.07)
    P(g, box(0.043, 0.08, 0.014), 'polymer_black', { color: 0x16181a }, 0, -0.002, bodyZ + s.bodyLen / 2 + 0.155)
  } else if (s.stock === 'compact') {
    // mag7: thick polymer tail block with sling loop
    P(g, box(0.042, 0.07, 0.1), 'polymer_black', { color: 0x25282a }, 0, 0.0, bodyZ + s.bodyLen / 2 + 0.05)
    P(g, box(0.045, 0.085, 0.014), 'polymer_black', { color: 0x16181a }, 0, -0.004, bodyZ + s.bodyLen / 2 + 0.105)
  }
  // sawedoff: no stock — bare grip + receiver ring

  buildGloves(g, team,
    { x: 0, y: s.stock === 'none' ? -0.045 : -0.06, z: s.stock === 'none' ? bodyZ + 0.06 : 0.035, rx: gripR + 0.1 },
    { x: 0, y: handY - 0.006, z: (pump ? pump.userData.homeZ as number : bodyZ - s.bodyLen / 2 - 0.1), rx: 0.28 })

  return {
    group: g, tip: new THREE.Vector3(0, boreY, s.muzzleZ), mag, pump,
    eject: new THREE.Vector3(s.bodyW / 2 + 0.004, boreY + 0.01, bodyZ + 0.03),
    muzzleLen: -s.muzzleZ + 0.02,
  }
}

// ---------------------------------------------------------------- Phase 7 MGs
// Machine-gun family (plan 7.3: "belt/mag box on the rifle family"). Both are
// belt-fed box-mag heavies: fat receiver, vented barrel shroud, bipod folded
// under the front, and a solid under-receiver ammo BOX as the mag group (it
// drops on reload like mag7's box mag — real MGs swap the whole box).
// m249 = conventional long SAW: carry handle, gas block, fixed stock.
// negev = compact IMI design: stubby chunky shroud with vent holes, slightly
// raked box, shorter everything. No bolt group — full-auto guns eject shells
// without a rechamber cycle.

interface MGSpec {
  bodyLen: number; bodyH: number; bodyW: number; bodyCol: number
  barrelR: number; barrelLen: number; muzzleZ: number
  shroudR: number; shroudLen: number        // perforated barrel shroud
  boxW: number; boxH: number; boxD: number; boxCol: number
  stockLen: number; stockCol: number
  carryHandle: boolean
  gasBlock: boolean                          // m249 front gas system
  boxRake: number                            // negev box sits slightly angled
}

const MGS: Record<'m249' | 'negev', MGSpec> = {
  m249: {
    bodyLen: 0.34, bodyH: 0.085, bodyW: 0.055, bodyCol: 0x2b3428,
    barrelR: 0.011, barrelLen: 0.30, muzzleZ: -0.72,
    shroudR: 0.017, shroudLen: 0.22,
    boxW: 0.055, boxH: 0.13, boxD: 0.075, boxCol: 0x1e2124,
    stockLen: 0.24, stockCol: 0x2b3428,
    carryHandle: true, gasBlock: true, boxRake: 0,
  },
  negev: {
    bodyLen: 0.30, bodyH: 0.09, bodyW: 0.058, bodyCol: 0x2a2d30,
    barrelR: 0.012, barrelLen: 0.24, muzzleZ: -0.60,
    shroudR: 0.023, shroudLen: 0.24,
    boxW: 0.06, boxH: 0.12, boxD: 0.082, boxCol: 0x232629,
    stockLen: 0.19, stockCol: 0x25282a,
    carryHandle: true, gasBlock: false, boxRake: 0.12,
  },
}

function buildMG(id: keyof typeof MGS, team: TeamId): ViewModel {
  const s = MGS[id]
  const g = new THREE.Group()
  const bodyZ = -s.bodyLen / 2 + 0.03
  const frontZ = bodyZ - s.bodyLen / 2
  // receiver — tall slab + top cover seam
  P(g, box(s.bodyW, s.bodyH, s.bodyLen), 'metal_dark', { color: s.bodyCol }, 0, 0.02, bodyZ)
  P(g, box(s.bodyW - 0.008, 0.012, s.bodyLen * 0.92), 'metal_dark', { color: 0x1a1d20 }, 0, 0.02 + s.bodyH / 2 + 0.004, bodyZ)
  // feed-tray cover hinge + side charging handle
  P(g, box(0.024, 0.009, 0.05), 'metal_dark', { color: 0x101214 }, s.bodyW / 2 + 0.005, 0.032, bodyZ + 0.05)
  P(g, box(0.006, 0.03, 0.014), 'metal_dark', { color: 0x101214 }, s.bodyW / 2 + 0.004, 0.028, bodyZ + 0.02)
  // carry handle over the top cover (both MGs — lugging weight is the look)
  if (s.carryHandle) {
    P(g, box(0.016, 0.024, id === 'negev' ? 0.13 : 0.10), 'metal_dark', { color: 0x1a1d20 }, 0, 0.02 + s.bodyH / 2 + 0.028, bodyZ + 0.02)
    P(g, box(0.012, 0.018, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.02 + s.bodyH / 2 + 0.016, bodyZ + (id === 'negev' ? 0.08 : 0.06))
    P(g, box(0.012, 0.018, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.02 + s.bodyH / 2 + 0.016, bodyZ - 0.03)
  }
  // barrel + perforated shroud + muzzle
  P(g, cyl(s.barrelR, s.barrelLen), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.02, s.muzzleZ + s.barrelLen / 2, q(90))
  P(g, cyl(s.shroudR, s.shroudLen, 14), 'metal_dark', { roughnessMul: 0.75, color: s.bodyCol }, 0, 0.02, s.muzzleZ + s.shroudLen / 2 + 0.02, q(90))
  for (let i = 0; i < 4; i++) {
    P(g, cyl(s.shroudR + 0.0015, 0.006, 14), 'metal_dark', { color: 0x16181a }, 0, 0.02, s.muzzleZ + 0.05 + i * (s.shroudLen / 4.4), q(90))
  }
  // bipod folded forward under the shroud (legs parallel to the barrel)
  P(g, cyl(0.004, 0.1, 8), 'metal_dark', { color: 0x16181a }, 0.012, 0.02 - s.shroudR - 0.013, s.muzzleZ + s.shroudLen / 2 + 0.045, q(90), q(9))
  P(g, cyl(0.004, 0.1, 8), 'metal_dark', { color: 0x16181a }, -0.012, 0.02 - s.shroudR - 0.013, s.muzzleZ + s.shroudLen / 2 + 0.045, q(90), -q(9))
  // m249 gas block + front sight / negev raised front sight
  if (s.gasBlock) {
    P(g, box(0.018, 0.028, 0.022), 'metal_dark', { color: 0x1a1d20 }, 0, 0.03, s.muzzleZ + s.shroudLen + 0.015)
    P(g, cyl(0.004, 0.05, 8), 'steel_blued', {}, 0, 0.038, s.muzzleZ + s.shroudLen - 0.02, 0, 0, q(90))
  }
  P(g, box(0.006, 0.034, 0.006), 'metal_dark', { color: 0x16181a }, 0, 0.05, s.muzzleZ + 0.028)
  // handguard shroud taper into the receiver
  P(g, box(s.bodyW - 0.006, s.bodyH - 0.024, 0.05), 'metal_dark', { color: s.bodyCol }, 0, 0.012, frontZ + 0.01)
  // grip + trigger
  P(g, box(0.005, 0.028, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.03, -0.02, 0.15)
  P(g, box(0.034, 0.095, 0.05), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.072, 0.02, 0.24)
  // ammo box (mag group — drops on reload): top latch ridge + front stub
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(s.boxW, s.boxH, s.boxD), 'polymer_black', { color: s.boxCol }, 0, -0.045 - s.boxH / 2, frontZ + 0.075, s.boxRake)
  P(mag, box(s.boxW + 0.004, 0.014, s.boxD + 0.006), 'metal_dark', { color: 0x141618 }, 0, -0.045 - 0.007, frontZ + 0.075, s.boxRake)
  P(mag, box(s.boxW - 0.02, 0.02, 0.012), 'metal_dark', { color: 0x101214 }, 0, -0.045 - 0.02, frontZ + 0.075 + s.boxD / 2 + 0.004, s.boxRake)
  // belt of rounds feeding out of the tray into the receiver front
  P(g, box(0.03, 0.012, 0.03), 'metal_dark', { color: 0x4a3b22 }, 0, -0.034, frontZ + 0.02)
  // stock: fixed polymer + butt pad (m249 long, negev stubby)
  P(g, box(s.bodyW - 0.004, 0.062, s.stockLen), 'polymer_black', { color: s.stockCol }, 0, 0.006, bodyZ + s.bodyLen / 2 + s.stockLen / 2 - 0.01)
  P(g, box(s.bodyW, 0.085, 0.015), 'polymer_black', { color: 0x16181a }, 0, -0.004, bodyZ + s.bodyLen / 2 + s.stockLen - 0.012)
  buildGloves(g, team,
    { x: 0, y: -0.068, z: 0.0, rx: 0.3 },
    { x: 0, y: -0.028, z: frontZ - 0.05, rx: 0.34 })
  return {
    group: g, tip: new THREE.Vector3(0, 0.02, s.muzzleZ), mag,
    eject: new THREE.Vector3(s.bodyW / 2 + 0.004, 0.045, bodyZ + 0.06),
  }
}

// ---------------------------------------------------------------- MP5-SD
function buildMP5(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver tube + grip frame
  P(g, cyl(0.024, 0.24, 14), 'metal_dark', { color: 0x232629 }, 0, 0.012, -0.15, q(90))
  P(g, box(0.04, 0.05, 0.11), 'polymer_black', { color: 0x222527 }, 0, -0.018, -0.055)
  P(g, box(0.036, 0.028, 0.05), 'polymer_black', { color: 0x1f2224 }, 0, -0.05, -0.105)
  // suppressor with vent rings
  P(g, cyl(0.023, 0.19, 14), 'metal_dark', {}, 0, 0.012, -0.36, q(90))
  for (let i = 0; i < 3; i++) {
    P(g, cyl(0.0245, 0.008, 14), 'metal_dark', { color: 0x16181a }, 0, 0.012, -0.30 - i * 0.06, q(90))
  }
  // hooded front sight + cocking handle
  P(g, box(0.004, 0.03, 0.004), 'metal_dark', { color: 0x16181a }, 0, 0.052, -0.255)
  P(g, box(0.024, 0.004, 0.008), 'metal_dark', { color: 0x16181a }, 0, 0.062, -0.255)
  P(g, box(0.004, 0.024, 0.008), 'metal_dark', { color: 0x16181a }, 0.012, 0.052, -0.255)
  P(g, box(0.004, 0.024, 0.008), 'metal_dark', { color: 0x16181a }, -0.012, 0.052, -0.255)
  P(g, box(0.022, 0.008, 0.06), 'steel_blued', {}, -0.032, 0.02, -0.19, 0, 0, 0.25)
  // rear drum sight
  P(g, cyl(0.012, 0.012, 10), 'metal_dark', { color: 0x16181a }, 0, 0.05, -0.03, q(90))
  // magazine (slight progressive curve)
  const mag = new THREE.Group()
  g.add(mag)
  for (let i = 0; i < 3; i++) {
    P(mag, box(0.025, 0.05, 0.05), 'polymer_black', { color: 0x1f2224 },
      0, -0.075 - i * 0.048, -0.105 - i * 0.014, -0.16 * i)
  }
  P(mag, box(0.028, 0.012, 0.055), 'polymer_black', { color: 0x16181a }, 0, -0.212, -0.126, -0.35)
  // fixed stock + butt pad
  P(g, box(0.038, 0.062, 0.19), 'polymer_black', { color: 0x25282a }, 0, 0.008, 0.115)
  P(g, box(0.041, 0.085, 0.015), 'polymer_black', { color: 0x16181a }, 0, 0.0, 0.215)
  // trigger
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.032, -0.03, 0.12)
  buildGloves(g, team, { x: 0, y: -0.05, z: 0.0, rx: 0.28 }, { x: 0, y: -0.03, z: -0.26, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.012, -0.465), mag, eject: new THREE.Vector3(0.03, 0.035, -0.11) }
}

// ---------------------------------------------------------------- Phase 4 SMGs
// Parametric SMG family (plan 4.2): one builder, per-weapon receiver/barrel/
// stock/mag specs. P90 (bullpup + top mag) and PP-Bizon (helical under-barrel
// drum) get dedicated builders below — their layouts break the convention.

interface SMGSpec {
  bodyLen: number; bodyH: number; bodyW: number; bodyCol: number
  barrelR: number; barrelLen: number; muzzleZ: number
  magIn: 'grip' | 'front'     // magazine well placement
  magLen: number
  stock: 'side' | 'none' | 'bullpup'
  frontGrip: boolean          // vertical foregrip (mp7)
  magRake: number             // grip rake (compact mag-in-grip SMGs)
  foreEnd: number             // left-hand z (handguard / front grip)
}

const SMGS: Record<'mp9' | 'mac10' | 'mp7' | 'ump45', SMGSpec> = {
  // CT compact: polymer, mag in the grip, stock folded alongside
  mp9:   { bodyLen: 0.20, bodyH: 0.062, bodyW: 0.042, bodyCol: 0x26292c, barrelR: 0.009, barrelLen: 0.06, muzzleZ: -0.215, magIn: 'grip', magLen: 0.16, stock: 'side', frontGrip: false, magRake: 0.20, foreEnd: -0.14 },
  // T boxy room-sweeper: tall receiver, fat barrel, bare back
  mac10: { bodyLen: 0.17, bodyH: 0.078, bodyW: 0.050, bodyCol: 0x2b2f33, barrelR: 0.014, barrelLen: 0.05, muzzleZ: -0.190, magIn: 'grip', magLen: 0.17, stock: 'none', frontGrip: false, magRake: 0.12, foreEnd: -0.10 },
  // slim PDW: rear-extended shell, front vertical grip
  mp7:   { bodyLen: 0.24, bodyH: 0.056, bodyW: 0.038, bodyCol: 0x232629, barrelR: 0.008, barrelLen: 0.06, muzzleZ: -0.280, magIn: 'grip', magLen: 0.15, stock: 'bullpup', frontGrip: true, magRake: 0.22, foreEnd: -0.17 },
  // chunky .45: tall receiver, big mag ahead of the guard, folded stock
  ump45: { bodyLen: 0.24, bodyH: 0.075, bodyW: 0.050, bodyCol: 0x25282a, barrelR: 0.010, barrelLen: 0.05, muzzleZ: -0.270, magIn: 'front', magLen: 0.22, stock: 'side', frontGrip: false, magRake: 0.26, foreEnd: -0.15 },
}

function buildSMG(id: keyof typeof SMGS, team: TeamId): ViewModel {
  const s = SMGS[id]
  const g = new THREE.Group()
  const bodyZ = -s.bodyLen / 2 + 0.03          // receiver rear edge at z +0.03
  // receiver + top rail strip with notches
  P(g, box(s.bodyW, s.bodyH, s.bodyLen), 'polymer_black', { color: s.bodyCol }, 0, 0.012, bodyZ)
  P(g, box(s.bodyW - 0.006, 0.007, s.bodyLen * 0.86), 'metal_dark', { color: 0x101214 }, 0, 0.012 + s.bodyH / 2 + 0.0035, bodyZ - 0.01)
  for (let i = 0; i < 5; i++) {
    P(g, box(s.bodyW - 0.004, 0.005, 0.011), 'metal_dark', { color: 0x0f1113 },
      0, 0.012 + s.bodyH / 2 + 0.005, bodyZ + 0.035 - i * (s.bodyLen / 5.5))
  }
  // sights (front post + white dot, rear notch)
  const sightY = 0.012 + s.bodyH / 2 + 0.011
  P(g, box(0.004, 0.016, 0.006), 'metal_dark', { color: 0x16181a }, 0, sightY, s.muzzleZ + s.barrelLen + 0.02)
  P(g, box(0.016, 0.010, 0.008), 'metal_dark', { color: 0x16181a }, 0, sightY, bodyZ + s.bodyLen - 0.02)
  basic(0xf4f4f4, g, box(0.0035, 0.0035, 0.002), 0, sightY + 0.008, s.muzzleZ + s.barrelLen + 0.02)
  // barrel (+ mac10's fat threaded muzzle nut)
  P(g, cyl(s.barrelR, s.barrelLen), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.012, s.muzzleZ + s.barrelLen / 2, q(90))
  if (id === 'mac10') P(g, cyl(s.barrelR + 0.004, 0.022, 10), 'metal_dark', { color: 0x101214 }, 0, 0.012, s.muzzleZ + 0.011, q(90))
  // charging handle nub on the right flank
  P(g, box(0.02, 0.008, 0.014), 'metal_dark', { color: 0x101214 }, s.bodyW / 2 + 0.006, 0.012 + s.bodyH / 2 - 0.012, bodyZ + 0.02)
  // trigger + guard + grip
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.025, -0.03, 0.15)
  P(g, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.045, -0.03)
  P(g, box(0.036, 0.105, 0.05), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.062, 0.018, s.magRake)
  // magazine (group: engine hides it mid-reload + spawns the dropped copy)
  const mag = new THREE.Group()
  g.add(mag)
  if (s.magIn === 'grip') {
    P(mag, box(0.03, s.magLen, 0.042), 'metal_dark', { color: 0x1b1e21 }, 0, -0.06, 0.015, s.magRake)
    P(mag, box(0.036, 0.011, 0.05), 'polymer_black', { color: 0x141618 }, 0, -0.06 - s.magLen / 2 - 0.006, 0.027, s.magRake)
  } else {
    // ump45: long straight mag ahead of the guard, slight forward rake
    P(mag, box(0.034, s.magLen, 0.052), 'polymer_black', { color: 0x1f2224 }, 0, -0.045 - s.magLen / 2, -0.135, -0.06)
    P(mag, box(0.04, 0.012, 0.058), 'metal_dark', { color: 0x141618 }, 0, -0.045 - s.magLen + 0.005, -0.142, -0.06)
  }
  // stock variants
  if (s.stock === 'side') {
    // folded alongside the receiver: bar + shoulder plate on the right flank
    P(g, box(0.012, 0.02, 0.15), 'metal_dark', { color: 0x1b1e21 }, s.bodyW / 2 + 0.013, 0.008, 0.09)
    P(g, box(0.014, 0.075, 0.028), 'polymer_black', { color: 0x1f2224 }, s.bodyW / 2 + 0.018, -0.014, 0.16)
  } else if (s.stock === 'bullpup') {
    // mp7: shell runs back into a cheek riser + butt pad
    P(g, box(s.bodyW - 0.004, s.bodyH - 0.006, 0.12), 'polymer_black', { color: s.bodyCol }, 0, 0.006, 0.13)
    P(g, box(s.bodyW, 0.016, 0.10), 'polymer_black', { color: 0x25282a }, 0, 0.032, 0.12)
    P(g, box(s.bodyW, 0.085, 0.014), 'polymer_black', { color: 0x16181a }, 0, -0.002, 0.192)
  } else {
    // mac10: bare back plate + end cap
    P(g, box(s.bodyW, s.bodyH, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.012, 0.036)
  }
  // mp7's vertical foregrip
  if (s.frontGrip) P(g, box(0.028, 0.06, 0.045), 'polymer_black', { color: 0x1f2224 }, 0, -0.045, s.foreEnd, -0.25)
  buildGloves(g, team, { x: 0, y: -0.06, z: 0.015, rx: 0.3 }, { x: 0, y: s.frontGrip ? -0.05 : -0.03, z: s.foreEnd, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.012, s.muzzleZ), mag, eject: new THREE.Vector3(s.bodyW / 2 + 0.004, 0.035, bodyZ + s.bodyLen * 0.3) }
}

// ---------------------------------------------------------------- P90
// Bullpup: one long shell, 50-rd magazine ON TOP (pulls UP on reload —
// engine's mag envelope already inserts along +y), slim coil-sleeved barrel.
function buildP90(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // shell + sloped nose
  P(g, box(0.05, 0.08, 0.40), 'polymer_black', { color: 0x2a2d30 }, 0, 0.0, -0.14)
  P(g, box(0.046, 0.05, 0.13), 'polymer_black', { color: 0x25282a }, 0, 0.026, -0.325, 0.35)
  // top magazine + witness slots along the spine
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.024, 0.02, 0.29), 'polymer_black', { color: 0x1f2224 }, 0, 0.055, -0.10)
  for (let i = 0; i < 5; i++) {
    P(mag, box(0.026, 0.004, 0.03), 'metal_dark', { color: 0x101214 }, 0, 0.065, -0.02 - i * 0.05)
  }
  // integrated ring sight housing + dark lens
  P(g, box(0.03, 0.018, 0.05), 'polymer_black', { color: 0x222527 }, 0, 0.062, 0.05)
  basic(0x101418, g, box(0.024, 0.012, 0.003), 0, 0.062, 0.024)
  // barrel + coil sleeve
  P(g, cyl(0.008, 0.09), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.008, -0.385, q(90))
  P(g, cyl(0.012, 0.045, 12), 'metal_dark', { color: 0x16181a }, 0, 0.008, -0.35, q(90))
  // forward grip ridge + rear grip shell (bullpup: grip ahead of trigger)
  P(g, box(0.03, 0.05, 0.06), 'polymer_black', { color: 0x25282a }, 0, -0.038, -0.20, 0.25)
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.032, 0.01, 0.15)
  P(g, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.052, 0.005)
  buildGloves(g, team, { x: 0, y: -0.048, z: -0.06, rx: 0.3 }, { x: 0, y: -0.038, z: -0.22, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.008, -0.43), mag, eject: new THREE.Vector3(0.026, 0.03, -0.02) }
}

// ---------------------------------------------------------------- PP-Bizon
// AK-family receiver + the identity part: 64-round helical drum under the
// barrel (engine's reload mag envelope lifts it into the well).
function buildBizon(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver + dust cover
  P(g, box(0.05, 0.055, 0.24), 'metal_dark', { color: 0x232629 }, 0, 0.012, -0.11)
  P(g, box(0.046, 0.02, 0.20), 'metal_dark', { color: 0x1b1e21 }, 0, 0.042, -0.12)
  // gas tube + barrel + threaded muzzle
  P(g, cyl(0.006, 0.10, 8), 'metal_dark', { color: 0x1b1e21 }, 0, 0.045, -0.30, q(90))
  P(g, cyl(0.010, 0.14), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.02, -0.30, q(90))
  P(g, cyl(0.013, 0.03, 10), 'metal_dark', { color: 0x101214 }, 0, 0.02, -0.375, q(90))
  // front sight post + rear notch
  P(g, box(0.004, 0.03, 0.004), 'metal_dark', { color: 0x16181a }, 0, 0.05, -0.34)
  P(g, box(0.014, 0.012, 0.008), 'metal_dark', { color: 0x16181a }, 0, 0.056, 0.005)
  // polymer handguard around the barrel root
  P(g, box(0.044, 0.04, 0.11), 'polymer_black', { color: 0x25282a }, 0, 0.018, -0.25)
  // skeleton polymer stock + butt pad
  P(g, box(0.042, 0.052, 0.16), 'polymer_black', { color: 0x25282a }, 0, 0.006, 0.14, 0.06)
  P(g, box(0.045, 0.08, 0.014), 'polymer_black', { color: 0x16181a }, 0, -0.004, 0.222)
  // grip + trigger + guard
  P(g, box(0.036, 0.10, 0.05), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.058, 0.02, 0.26)
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.028, -0.02, 0.15)
  P(g, box(0.026, 0.004, 0.05), 'metal_dark', { color: 0x232629 }, 0, -0.048, -0.02)
  // helical drum (with ring ribs reading as the spiral feed) — the mag group
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, cyl(0.027, 0.19, 16), 'polymer_black', { color: 0x1f2224, density: 2.5 }, 0, -0.028, -0.24, q(90))
  for (let i = 0; i < 4; i++) {
    P(mag, cyl(0.0285, 0.008, 16), 'polymer_black', { color: 0x141618 }, 0, -0.028, -0.17 - i * 0.045, q(90))
  }
  buildGloves(g, team, { x: 0, y: -0.055, z: 0.03, rx: 0.28 }, { x: 0, y: -0.06, z: -0.23, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.02, -0.395), mag, eject: new THREE.Vector3(0.03, 0.04, -0.06) }
}

