// ---------------------------------------------------------------- Glock-18 / USP-S
function buildPistol(weapon: 'glock' | 'usp', team: TeamId): ViewModel {
  const g = new THREE.Group()
  const usp = weapon === 'usp'
  const slideLen = usp ? 0.195 : 0.185
  const slideH = usp ? 0.048 : 0.042
  const slideCol = usp ? 0x2c3033 : 0x26292c
  // slide
  const slide = P(g, box(usp ? 0.038 : 0.036, slideH, slideLen), 'metal_dark',
    { color: slideCol, roughnessMul: 0.8, normalScale: 0.8 }, 0, 0.02, -slideLen / 2 + 0.02)
  // barrel + muzzle
  if (usp) {
    P(g, cyl(0.0165, 0.135, 14), 'metal_dark', { roughnessMul: 0.75 }, 0, 0.012, -0.215, q(90))
  } else {
    P(g, cyl(0.0075, 0.022), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.014, -0.172, q(90))
  }
  // slide serrations
  for (let i = 0; i < 4; i++) {
    P(g, box((usp ? 0.04 : 0.038), 0.026, 0.0025), 'metal_dark', { color: 0x0f1113 }, 0, 0.022, 0.045 - i * 0.007)
  }
  // sights (white dots)
  P(g, box(0.005, 0.009, 0.007), 'metal_dark', { color: 0x50555a }, 0, 0.048, -slideLen / 2 - 0.075)
  P(g, box(0.016, 0.008, 0.008), 'metal_dark', { color: 0x50555a }, 0, 0.048, 0.055)
  basic(0xf4f4f4, g, box(0.004, 0.004, 0.003), 0, 0.053, -slideLen / 2 - 0.075)
  // frame + rail + magwell flare
  P(g, box(0.034, 0.03, 0.13), 'polymer_black', { color: 0x222527 }, 0, -0.008, -0.04)
  P(g, box(0.028, 0.008, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.026, -0.105)
  P(g, box(0.04, 0.012, 0.052), 'polymer_black', { color: 0x191c1e }, 0, -0.098, 0.028, 0.2)
  // trigger + guard
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.025, -0.05, 0.15)
  P(g, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.046, -0.05)
  // grip (heavy stipple) + magazine
  P(g, box(0.034, 0.105, 0.048), 'polymer_black', { density: 9 }, 0, -0.068, 0.015, 0.22)
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.03, 0.095, 0.042), 'metal_dark', { color: 0x1b1e21 }, 0, -0.066, 0.012, 0.22)
  P(mag, box(0.036, 0.011, 0.05), 'polymer_black', { color: 0x141618 }, 0, -0.118, 0.024, 0.22)
  buildGloves(g, team, { x: 0, y: -0.065, z: 0.028, rx: 0.3 })
  const tipZ = usp ? -0.285 : -0.185
  return { group: g, tip: new THREE.Vector3(0, 0.014, tipZ), mag, slide, eject: new THREE.Vector3(0.022, 0.038, -0.1) }
}

// ---------------------------------------------------------------- Phase 3 pistols
// Parametric semi-auto family (plan 3.2): one builder, per-weapon slide/frame
// proportions + finish colors. The dual berettas (mirrored pair), the R8
// revolver (cylinder + underlug) and the zeus (taser body) get dedicated
// builders below.

interface SemiSpec {
  slideLen: number; slideH: number; slideW: number; slideCol: number
  barrelMuzzle: number      // muzzle z (negative)
  barrelLen: number
  frameCol: number
  gripCol: number
  gripRake: number
  magH: number
  shroud?: boolean          // tec-9 vented barrel shroud
  rail?: boolean            // under-frame accessory rail
}

const SEMI: Record<'p250' | 'fiveseven' | 'tec9' | 'cz75' | 'hkp2000', SemiSpec> = {
  // compact + chunky
  p250: { slideLen: 0.185, slideH: 0.046, slideW: 0.038, slideCol: 0x26292c, barrelMuzzle: -0.20, barrelLen: 0.03, frameCol: 0x222527, gripCol: 0x1f2224, gripRake: 0.22, magH: 0.09 },
  // long thin slide, big 20-rd mag
  fiveseven: { slideLen: 0.215, slideH: 0.040, slideW: 0.036, slideCol: 0x2c3033, barrelMuzzle: -0.225, barrelLen: 0.025, frameCol: 0x232629, gripCol: 0x1f2224, gripRake: 0.20, magH: 0.105, rail: true },
  // boxy steel, near-vertical grip, vented shroud
  tec9: { slideLen: 0.20, slideH: 0.052, slideW: 0.044, slideCol: 0x33383d, barrelMuzzle: -0.24, barrelLen: 0.05, frameCol: 0x2b2f33, gripCol: 0x222527, gripRake: 0.10, magH: 0.115, shroud: true },
  // all-steel service pistol, railed frame
  cz75: { slideLen: 0.195, slideH: 0.047, slideW: 0.039, slideCol: 0x2b2f33, barrelMuzzle: -0.21, barrelLen: 0.03, frameCol: 0x26292c, gripCol: 0x1f2224, gripRake: 0.26, magH: 0.10, rail: true },
  // glock-ish proportions, lighter slide finish
  hkp2000: { slideLen: 0.185, slideH: 0.040, slideW: 0.035, slideCol: 0x303539, barrelMuzzle: -0.195, barrelLen: 0.02, frameCol: 0x222527, gripCol: 0x1f2224, gripRake: 0.24, magH: 0.09 },
}

function buildSemiPistol(id: keyof typeof SEMI, team: TeamId): ViewModel {
  const s = SEMI[id]
  const g = new THREE.Group()
  const slideZ = -s.slideLen / 2 + 0.02
  const slideFront = -s.slideLen + 0.02
  // slide
  const slide = P(g, box(s.slideW, s.slideH, s.slideLen), 'metal_dark',
    { color: s.slideCol, roughnessMul: 0.8, normalScale: 0.8 }, 0, 0.02, slideZ)
  // barrel (muzzle at barrelMuzzle)
  P(g, cyl(0.0075, s.barrelLen), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.018, s.barrelMuzzle + s.barrelLen / 2, q(90))
  if (s.shroud) {
    // tec-9 vented barrel shroud
    P(g, box(s.slideW + 0.004, 0.03, 0.08), 'metal_dark', { color: s.slideCol }, 0, 0.018, s.barrelMuzzle + 0.05)
    for (let i = 0; i < 3; i++) {
      P(g, box(0.005, 0.031, 0.012), 'metal_dark', { color: 0x0f1113 }, s.slideW / 2 + 0.002, 0.018, s.barrelMuzzle + 0.07 - i * 0.022)
      P(g, box(0.005, 0.031, 0.012), 'metal_dark', { color: 0x0f1113 }, -s.slideW / 2 - 0.002, 0.018, s.barrelMuzzle + 0.07 - i * 0.022)
    }
  }
  // slide serrations
  for (let i = 0; i < 4; i++) {
    P(g, box(s.slideW + 0.002, s.slideH * 0.55, 0.0025), 'metal_dark', { color: 0x0f1113 }, 0, 0.022, 0.045 - i * 0.007)
  }
  // sights + white front dot
  P(g, box(0.005, 0.009, 0.007), 'metal_dark', { color: 0x50555a }, 0, 0.02 + s.slideH / 2 + 0.004, slideFront - 0.0025)
  P(g, box(0.016, 0.008, 0.008), 'metal_dark', { color: 0x50555a }, 0, 0.02 + s.slideH / 2 + 0.004, 0.055)
  basic(0xf4f4f4, g, box(0.004, 0.004, 0.003), 0, 0.02 + s.slideH / 2 + 0.008, slideFront - 0.0025)
  // frame + optional under rail
  P(g, box(s.slideW - 0.003, 0.03, 0.13), 'polymer_black', { color: s.frameCol }, 0, -0.008, -0.04)
  if (s.rail) {
    for (let i = 0; i < 3; i++) {
      P(g, box(0.024, 0.008, 0.014), 'polymer_black', { color: 0x191c1e }, 0, -0.026, -0.085 + i * 0.022)
    }
  }
  // trigger + guard
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.025, -0.05, 0.15)
  P(g, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.046, -0.05)
  // grip
  P(g, box(s.slideW - 0.002, s.magH + 0.02, 0.048), 'polymer_black', { density: 9, color: s.gripCol }, 0, -0.06, 0.015, s.gripRake)
  // magazine
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(s.slideW - 0.006, s.magH, 0.042), 'metal_dark', { color: 0x1b1e21 }, 0, -0.058, 0.012, s.gripRake)
  P(mag, box(s.slideW - 0.002, 0.011, 0.05), 'polymer_black', { color: 0x141618 }, 0, -0.058 - s.magH / 2 - 0.006, 0.024, s.gripRake)
  buildGloves(g, team, { x: 0, y: -0.06, z: 0.028, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.018, s.barrelMuzzle), mag, slide, eject: new THREE.Vector3(0.022, 0.038, -0.1) }
}

// ---------------------------------------------------------------- Dual Berettas
// Two Beretta 92s, one per hand (plan: "two viewmodels alternating hands").
// The engine alternates fire left/right via slide / slideL.
function berettaBody(parent: THREE.Object3D, xOff: number, mirror: boolean): { slide: THREE.Mesh; mag: THREE.Group } {
  const s = mirror ? -1 : 1
  // slide (beretta's open-top) + exposed chrome-ish barrel hood
  const slide = P(parent, box(0.036, 0.044, 0.19), 'metal_dark',
    { color: 0x2c3033, roughnessMul: 0.8, normalScale: 0.8 }, xOff, 0.02, -0.075)
  P(parent, cyl(0.0085, 0.03), 'steel_blued', { roughnessMul: 0.4, metalness: 0.95 }, xOff, 0.024, -0.185, q(90))
  // front sight + white dot
  P(parent, box(0.005, 0.009, 0.007), 'metal_dark', { color: 0x50555a }, xOff, 0.046, -0.167)
  basic(0xf4f4f4, parent, box(0.004, 0.004, 0.003), xOff, 0.05, -0.167)
  // serrations
  for (let i = 0; i < 4; i++) {
    P(parent, box(0.038, 0.026, 0.0025), 'metal_dark', { color: 0x0f1113 }, xOff, 0.022, 0.03 - i * 0.007)
  }
  // frame + trigger + guard
  P(parent, box(0.033, 0.03, 0.125), 'polymer_black', { color: 0x222527 }, xOff, -0.008, -0.04)
  P(parent, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, xOff, -0.025, -0.05, 0.15)
  P(parent, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, xOff, -0.046, -0.05)
  // grip
  P(parent, box(0.034, 0.105, 0.048), 'polymer_black', { density: 9, color: 0x1f2224 }, xOff, -0.06, 0.015, 0.24)
  // magazine (in the grip)
  const mag = new THREE.Group()
  parent.add(mag)
  P(mag, box(0.03, 0.095, 0.042), 'metal_dark', { color: 0x1b1e21 }, xOff, -0.058, 0.012, 0.24)
  P(mag, box(0.036, 0.011, 0.05), 'polymer_black', { color: 0x141618 }, xOff, -0.11, 0.024, 0.24)
  // ambidextrous safety nub
  P(parent, box(0.006, 0.012, 0.012), 'metal_dark', { color: 0x101214 }, xOff + s * 0.021, 0.012, -0.01)
  return { slide, mag }
}

function buildElites(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // right-hand gun (fires first) + mirrored left-hand gun
  const right = berettaBody(g, 0.075, false)
  const left = berettaBody(g, -0.14, true)
  // right hand on the right gun, mirrored glove = left hand on the left gun
  buildGloves(g, team, { x: 0.075, y: -0.06, z: 0.04, rx: 0.3 })
  buildGloves(g, team, { x: -0.14, y: -0.06, z: 0.04, rx: 0.3 }, undefined, true)
  return {
    group: g,
    tip: new THREE.Vector3(0.075, 0.02, -0.20),
    mag: right.mag,
    slide: right.slide,
    slideL: left.slide,
    eject: new THREE.Vector3(0.09, 0.04, -0.1),
  }
}

// ---------------------------------------------------------------- R8 Revolver
function buildRevolver(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // frame block + top strap
  P(g, box(0.036, 0.05, 0.08), 'steel_blued', { color: 0x2c3033, roughnessMul: 0.7 }, 0, 0.005, -0.02)
  P(g, box(0.012, 0.01, 0.05), 'steel_blued', {}, 0, 0.048, -0.05)
  // 8-shot cylinder + chamber ring
  P(g, cyl(0.021, 0.052, 16), 'steel_blued', { color: 0x2b2f33, roughnessMul: 0.6 }, 0, 0.012, -0.115, q(90))
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2
    P(g, cyl(0.0035, 0.054, 8), 'metal_dark', { color: 0x0f1113 },
      Math.cos(a) * 0.013, 0.012 + Math.sin(a) * 0.013, -0.115, q(90))
  }
  // barrel + underlug + ejector rod
  P(g, cyl(0.011, 0.16), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.02, -0.225, q(90))
  P(g, box(0.013, 0.012, 0.15), 'steel_blued', {}, 0, 0.003, -0.225)
  P(g, cyl(0.0035, 0.11, 8), 'metal_dark', { color: 0x33383d, metalness: 0.9, roughnessMul: 0.4 }, 0, 0.004, -0.215, q(90))
  // hammer + sights
  P(g, box(0.008, 0.022, 0.014), 'metal_dark', { color: 0x101214 }, 0, 0.042, 0.014, -0.45)
  P(g, box(0.004, 0.014, 0.012), 'metal_dark', { color: 0x50555a }, 0, 0.042, -0.30)
  P(g, box(0.01, 0.006, 0.008), 'metal_dark', { color: 0x50555a }, 0, 0.054, -0.02)
  // grip + trigger + guard
  P(g, box(0.034, 0.10, 0.046), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.058, 0.02, 0.3)
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.028, -0.035, 0.2)
  P(g, box(0.026, 0.004, 0.05), 'metal_dark', { color: 0x232629 }, 0, -0.046, -0.04)
  buildGloves(g, team, { x: 0, y: -0.068, z: 0.03, rx: 0.32 })
  return { group: g, tip: new THREE.Vector3(0, 0.02, -0.31), eject: new THREE.Vector3(0.024, 0.04, -0.11) }
}

// ---------------------------------------------------------------- Zeus x27
function buildTaser(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // body: boxy polymer with the yellow top shell
  P(g, box(0.05, 0.06, 0.16), 'polymer_black', { color: 0x222527 }, 0, 0.008, -0.05)
  P(g, box(0.052, 0.016, 0.15), 'polymer_black', { color: 0xc9a227, roughnessMul: 0.55 }, 0, 0.044, -0.05)
  // front plate + twin electrodes (the arc gap)
  P(g, box(0.05, 0.055, 0.02), 'metal_dark', { color: 0x191c1e }, 0, 0.008, -0.145)
  P(g, cyl(0.0035, 0.07, 8), 'metal_dark', { color: 0xb9c2c9, metalness: 1.0, roughnessMul: 0.3 }, 0.013, 0.012, -0.185, q(90))
  P(g, cyl(0.0035, 0.07, 8), 'metal_dark', { color: 0xb9c2c9, metalness: 1.0, roughnessMul: 0.3 }, -0.013, 0.012, -0.185, q(90))
  // green ready-LED + side switch
  basic(0x30ff60, g, box(0.006, 0.005, 0.006), 0.021, 0.055, 0.005)
  P(g, box(0.01, 0.006, 0.02), 'metal_dark', { color: 0x101214 }, -0.027, 0.03, -0.02)
  // grip + trigger guard
  P(g, box(0.036, 0.10, 0.05), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.058, 0.02, 0.22)
  P(g, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.046, -0.045)
  buildGloves(g, team, { x: 0, y: -0.062, z: 0.028, rx: 0.28 })
  return { group: g, tip: new THREE.Vector3(0, 0.012, -0.22), eject: new THREE.Vector3(0.022, 0.04, -0.08) }
}

// ---------------------------------------------------------------- knife (M9 bayonet style)
function buildKnife(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // blade (bright ground steel) + clip point tip + fuller groove
  P(g, box(0.012, 0.036, 0.17), 'metal_dark',
    { color: 0xcdd3d9, metalness: 1.0, roughnessMul: 0.35, normalScale: 0.7 }, 0, 0.016, -0.14)
  P(g, box(0.012, 0.026, 0.06), 'metal_dark',
    { color: 0xcdd3d9, metalness: 1.0, roughnessMul: 0.35, normalScale: 0.7 }, 0, 0.024, -0.24, -0.14)
  P(g, box(0.013, 0.009, 0.11), 'metal_dark',
    { color: 0x6f767c, metalness: 1.0, roughnessMul: 0.6 }, 0, 0.024, -0.115)
  // crossguard + handle + pommel
  P(g, box(0.012, 0.08, 0.016), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.002, -0.045)
  P(g, box(0.023, 0.033, 0.105), 'polymer_black', { density: 9 }, 0, 0.0, 0.016)
  for (let i = 0; i < 3; i++) {
    P(g, box(0.0245, 0.006, 0.012), 'polymer_black', { color: 0x14161a, density: 9 }, 0, -0.008 + i * 0.008, -0.012 + i * 0.032)
  }
  P(g, box(0.026, 0.037, 0.022), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.0, 0.075)
  buildGloves(g, team, { x: 0, y: 0.0, z: 0.02, rx: 0.12 })
  return { group: g, tip: new THREE.Vector3(0, 0.022, -0.28) }
}

// ---------------------------------------------------------------- C4
let keypadTex: THREE.Texture | null = null
function getKeypadTex(): THREE.Texture {
  if (keypadTex) return keypadTex
  const c = document.createElement('canvas')
  c.width = 256; c.height = 256
  const ctx = c.getContext('2d')!
  ctx.fillStyle = '#181b16'
  ctx.fillRect(0, 0, 256, 256)
  ctx.fillStyle = '#232720'
  for (let gy = 0; gy < 3; gy++) for (let gx = 0; gx < 3; gx++) {
    ctx.fillRect(16 + gx * 80, 16 + gy * 80, 64, 64)
  }
  ctx.fillStyle = '#c8d4b0'
  ctx.font = 'bold 40px monospace'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9']
  keys.forEach((k, i) => ctx.fillText(k, 48 + (i % 3) * 80, 48 + Math.floor(i / 3) * 80))
  keypadTex = new THREE.CanvasTexture(c)
  keypadTex.colorSpace = THREE.SRGBColorSpace
  return keypadTex
}

function buildC4(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // explosive block body
  P(g, box(0.15, 0.06, 0.19), 'enamel_od', { color: 0x5a5c42, roughnessMul: 1.1 }, 0, 0, -0.09)
  // straps
  P(g, box(0.152, 0.062, 0.013), 'polymer_black', { color: 0x121311, density: 2 }, 0, 0, -0.03)
  P(g, box(0.152, 0.062, 0.013), 'polymer_black', { color: 0x121311, density: 2 }, 0, 0, -0.15)
  // PCB panel + components
  P(g, box(0.11, 0.005, 0.14), 'pcb_green', { normalScale: 1.3 }, -0.012, 0.032, -0.10)
  for (let i = 0; i < 3; i++) {
    P(g, box(0.018, 0.007, 0.028), 'metal_dark', { color: 0x0c0d0e }, -0.042 + i * 0.03, 0.038, -0.135)
  }
  P(g, cyl(0.006, 0.014, 8), 'metal_dark', { color: 0x1e2226 }, -0.03, 0.039, -0.085)
  P(g, cyl(0.005, 0.012, 8), 'metal_dark', { color: 0x3a2e1a }, 0.012, 0.038, -0.075)
  P(g, box(0.03, 0.012, 0.035), 'metal_dark', { color: 0x101214 }, 0.032, 0.038, -0.135)
  // keypad
  const kp = new THREE.Mesh(box(0.05, 0.006, 0.055), new THREE.MeshStandardMaterial({
    map: getKeypadTex(), roughness: 0.75, metalness: 0.1,
  }))
  kp.position.set(-0.012, 0.033, -0.035)
  g.add(kp)
  // screen + LED (blinks)
  basic(0x0d1f0d, g, box(0.03, 0.004, 0.018), -0.012, 0.033, -0.005)
  const led = basic(0xff2020, g, box(0.008, 0.006, 0.008), 0.03, 0.034, -0.005)
  // det wires to the side
  P(g, cyl(0.003, 0.05, 6), 'metal_dark', { color: 0x181a1c }, 0.07, 0.03, -0.06, 0, 0, q(55))
  P(g, cyl(0.003, 0.04, 6), 'metal_dark', { color: 0x301c10 }, 0.065, 0.03, -0.1, 0, 0, q(70))
  // left hand cupping the block from below
  P(g, box(0.055, 0.06, 0.1), 'glove_fabric', { color: 0x232527 }, 0.01, -0.062, -0.09)
  P(g, box(0.075, 0.075, 0.045), 'polymer_black', { color: CUFF[team], density: 2 }, 0.045, -0.12, -0.03, 0.4)
  P(g, box(0.07, 0.072, 0.3), 'glove_fabric', {}, 0.08, -0.19, 0.09, 0.55, -0.25, -0.08)
  return { group: g, tip: new THREE.Vector3(0, 0, -0.2), led }
}

// ---------------------------------------------------------------- grenades (Phase 8)
// Hand-held viewmodels: each kind gets a distinct silhouette (HE olive ball,
// flash steel cylinder w/ blue band, smoke grey can w/ red band, molotov
// bottle + rag, incendiary canister w/ white stripe, decoy box + antenna).
// The pin/lever assembly is a separate group the engine rotates out on throw.
function buildGrenade(weapon: 'flash' | 'he' | 'smoke' | 'molotov' | 'inc' | 'decoy', team: TeamId): ViewModel {
  const g = new THREE.Group()
  const pin = new THREE.Group()

  if (weapon === 'he') {
    // olive sphere + spoon lever + top fuze well
    P(g, new THREE.SphereGeometry(0.052, 14, 12), 'enamel_od', { color: 0x39402c, roughnessMul: 1.15 }, 0, 0.015, -0.09)
    P(g, cyl(0.014, 0.02, 8), 'metal_dark', { color: 0x2c3122 }, 0, 0.072, -0.09)
    P(g, box(0.014, 0.005, 0.085), 'metal_dark', { color: 0x8a8f96, metalness: 1.0, roughnessMul: 0.35 }, 0.012, 0.055, -0.075, q(14))
    basic(0x2f3a22, g, box(0.05, 0.012, 0.02), 0, 0.012, -0.038)
  } else if (weapon === 'flash') {
    // steel cylinder + blue band + lever
    P(g, cyl(0.03, 0.115, 14), 'metal_dark', { color: 0x8b9096, metalness: 0.9, roughnessMul: 0.4 }, 0, 0.015, -0.09)
    P(g, cyl(0.031, 0.02, 14), 'metal_dark', { color: 0x3556a8, roughnessMul: 0.6 }, 0, 0.038, -0.09)
    P(g, cyl(0.031, 0.014, 14), 'metal_dark', { color: 0x8b9096, metalness: 0.9, roughnessMul: 0.4 }, 0, -0.045, -0.09)
    P(g, box(0.012, 0.004, 0.09), 'metal_dark', { color: 0x8a8f96, metalness: 1.0, roughnessMul: 0.35 }, 0.011, 0.05, -0.078, q(10))
  } else if (weapon === 'smoke') {
    // grey-green can + red band + top cap
    P(g, cyl(0.033, 0.125, 14), 'metal_dark', { color: 0x5b6157, metalness: 0.6, roughnessMul: 0.55 }, 0, 0.015, -0.09)
    P(g, cyl(0.034, 0.018, 14), 'metal_dark', { color: 0x9c3b30, roughnessMul: 0.6 }, 0, 0.032, -0.09)
    P(g, cyl(0.02, 0.014, 10), 'metal_dark', { color: 0x40443d }, 0, 0.078, -0.09)
    P(g, box(0.012, 0.004, 0.095), 'metal_dark', { color: 0x8a8f96, metalness: 1.0, roughnessMul: 0.35 }, 0.011, 0.05, -0.08, q(10))
  } else if (weapon === 'molotov') {
    // glass bottle + neck + fuel tint + rag
    P(g, cyl(0.036, 0.125, 12), 'metal_dark', { color: 0x7a4f1e, metalness: 0.15, roughnessMul: 0.25 }, 0, 0.015, -0.09)
    P(g, cyl(0.024, 0.115, 12), 'metal_dark', { color: 0x3d2c12, metalness: 0.05, roughnessMul: 0.3 }, 0, 0.012, -0.088)
    P(g, cyl(0.013, 0.045, 10), 'metal_dark', { color: 0x6a4a22, metalness: 0.1, roughnessMul: 0.35 }, 0, 0.09, -0.09)
    P(g, box(0.02, 0.05, 0.02), 'polymer_black', { color: 0x4a6612, density: 6 }, 0, 0.125, -0.09, q(-8), 0, q(10))
    basic(0xff9a30, g, box(0.008, 0.012, 0.008), 0, 0.155, -0.09) // ember tip
  } else if (weapon === 'inc') {
    // CT incendiary: sealed metal canister + white stripe
    P(g, cyl(0.034, 0.12, 14), 'metal_dark', { color: 0x6a3b1c, metalness: 0.75, roughnessMul: 0.45 }, 0, 0.015, -0.09)
    P(g, cyl(0.035, 0.016, 14), 'metal_dark', { color: 0xc7c2ba, roughnessMul: 0.5 }, 0, 0.012, -0.09)
    P(g, box(0.012, 0.004, 0.09), 'metal_dark', { color: 0x8a8f96, metalness: 1.0, roughnessMul: 0.35 }, 0.011, 0.052, -0.078, q(10))
  } else { // decoy
    // brown box + antenna + blinking red dot
    P(g, box(0.07, 0.055, 0.05), 'polymer_black', { color: 0x4a4238, roughnessMul: 1.2 }, 0, 0.012, -0.09)
    P(g, cyl(0.004, 0.085, 6), 'metal_dark', { color: 0x1c1c1c, metalness: 1.0 }, 0, 0.078, -0.078, q(12))
    basic(0xd02020, g, box(0.008, 0.006, 0.008), 0.032, 0.04, -0.112)
  }

  // pin/lever assembly at the top — rotates away when the throw releases it
  P(pin, cyl(0.009, 0.012, 8), 'metal_dark', { color: 0xb9c2c9, metalness: 1.0, roughnessMul: 0.3 }, 0, 0.082, -0.093, 0, 0, q(90))
  P(pin, new THREE.TorusGeometry(0.016, 0.0028, 8, 18), 'metal_dark', { color: 0xb9c2c9, metalness: 1.0, roughnessMul: 0.3 }, 0.03, 0.088, -0.093, q(78), 0, 0)
  g.add(pin)

  // right hand cradling the grenade
  buildGloves(g, team, { x: 0.002, y: -0.02, z: -0.02, rx: 0.5 })
  return { group: g, tip: new THREE.Vector3(0, 0.05, -0.16), pin }
}

// ---------------------------------------------------------------- dispatcher
const VM_BASE = new THREE.Vector3(0.26, -0.24, -0.45)

/** Build the first-person viewmodel for a weapon (cached by the engine). */
export function buildViewModel(weapon: WeaponId, team: TeamId): ViewModel {
  switch (weapon) {
    case 'ak47': return buildAK(team)
    case 'm4': return buildM4(team)
    case 'awp': return buildAWP(team)
    case 'galil': case 'famas': case 'sg553': case 'aug': case 'm4a1s':
      return buildRifle(weapon, team)
    case 'ssg08': case 'scar20': case 'g3sg1':
      return buildSniper(weapon, team)
    case 'nova': case 'xm1014': case 'mag7': case 'sawedoff':
      return buildShotgun(weapon, team)
    case 'm249': case 'negev':
      return buildMG(weapon, team)
    case 'mp5': return buildMP5(team)
    case 'mp9': case 'mac10': case 'mp7': case 'ump45':
      return buildSMG(weapon, team)
    case 'p90': return buildP90(team)
    case 'bizon': return buildBizon(team)
    case 'deagle': return buildDeagle(team)
    case 'glock': case 'usp': return buildPistol(weapon, team)
    case 'p250': case 'fiveseven': case 'tec9': case 'cz75': case 'hkp2000':
      return buildSemiPistol(weapon, team)
    case 'elites': return buildElites(team)
    case 'revolver': return buildRevolver(team)
    case 'taser': return buildTaser(team)
    case 'knife': return buildKnife(team)
    case 'c4': return buildC4(team)
    case 'flash': case 'he': case 'smoke':
    case 'molotov': case 'inc': case 'decoy':
      return buildGrenade(weapon, team)
    default: return buildKnife(team)
  }
}

/** Base position of a viewmodel group relative to the camera. */
export function vmBase(weapon: WeaponId): THREE.Vector3 {
  const off = weapon === 'c4' ? new THREE.Vector3(-0.1, -0.075, 0.02)
    : weapon === 'knife' ? new THREE.Vector3(0.24, -0.25, -0.4)
    : weapon === 'awp' ? new THREE.Vector3(0.24, -0.235, -0.43)
    : WEAPONS[weapon]?.throwable ? new THREE.Vector3(0.24, -0.245, -0.42)
    : VM_BASE.clone()
  return off
}

// ---------------------------------------------------------------- remote player guns
/**
 * Low-detail textured gun held by remote players. Origin at the grip,
 * muzzle toward -z; position it at the hand in players.ts.
 */
export function buildRemoteGun(weaponId: string): THREE.Group {
  const g = new THREE.Group()
  switch (weaponId) {
    case 'ak47':
      P(g, box(0.05, 0.06, 0.3), 'steel_blued', {}, 0, 0, 0.02)
      P(g, cyl(0.009, 0.34), 'steel_blued', {}, 0, 0.01, -0.24, q(90))
      P(g, box(0.04, 0.045, 0.14), 'wood_laminate', {}, 0, 0.0, -0.16)
      P(g, box(0.045, 0.1, 0.07), 'metal_dark', { roughnessMul: 0.8 }, 0, -0.09, -0.03, -0.2)
      P(g, box(0.035, 0.05, 0.18), 'wood_laminate', {}, 0, -0.01, 0.2)
      break
    case 'm4':
      P(g, box(0.045, 0.05, 0.24), 'polymer_black', { color: 0x26292c }, 0, 0, 0)
      P(g, cyl(0.008, 0.26), 'steel_blued', {}, 0, 0.01, -0.22, q(90))
      P(g, box(0.04, 0.045, 0.18), 'polymer_black', { color: 0x25282a }, 0, 0, -0.16)
      P(g, box(0.035, 0.1, 0.05), 'polymer_black', { color: 0x1f2224 }, 0, -0.08, -0.02, -0.06)
      P(g, box(0.035, 0.07, 0.14), 'polymer_black', { color: 0x26292c }, 0, 0, 0.2)
      break
    case 'awp':
      P(g, box(0.045, 0.055, 0.26), 'steel_blued', {}, 0, 0, 0)
      P(g, cyl(0.011, 0.44), 'steel_blued', {}, 0, 0.015, -0.33, q(90))
      P(g, cyl(0.018, 0.2, 12), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.07, -0.06, q(90))
      P(g, box(0.045, 0.08, 0.24), 'enamel_od', {}, 0, -0.01, 0.18)
      P(g, box(0.035, 0.07, 0.08), 'polymer_black', { color: 0x1f2224 }, 0, -0.06, -0.02, -0.06)
      break
    // ---- Phase 5 rifles: low-detail silhouettes, scoped/optic/suppressor flavor
    case 'galil': case 'sg553': case 'm4a1s': {
      P(g, box(0.045, 0.055, 0.26), 'polymer_black', { color: 0x26292c }, 0, 0.01, -0.06)
      P(g, box(0.04, 0.045, 0.16), 'polymer_black', { color: 0x25282a }, 0, 0.01, -0.24)
      P(g, cyl(0.008, 0.2), 'steel_blued', {}, 0, 0.014, -0.38, q(90))
      if (weaponId === 'm4a1s') {
        P(g, cyl(0.014, 0.12, 12), 'metal_dark', { roughnessMul: 0.75 }, 0, 0.014, -0.5, q(90))
      }
      if (weaponId === 'sg553') P(g, cyl(0.014, 0.07, 10), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.065, -0.1, q(90))
      P(g, box(0.03, 0.14, 0.04), 'metal_dark', { color: 0x1b1e21 }, 0, -0.1, -0.08, -0.08)
      P(g, box(0.032, 0.05, 0.12), 'polymer_black', { color: 0x25282a }, 0, 0.005, 0.12)
      break
    }
    case 'famas': case 'aug': {
      P(g, box(0.042, 0.06, 0.34), 'polymer_black', { color: weaponId === 'aug' ? 0x2d7d4f : 0x2a2d30 }, 0, 0.01, -0.08)
      P(g, cyl(0.008, 0.12), 'steel_blued', {}, 0, 0.012, -0.3, q(90))
      if (weaponId === 'aug') P(g, cyl(0.016, 0.13, 10), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.07, -0.14, q(90))
      else P(g, box(0.02, 0.026, 0.2), 'polymer_black', { color: 0x2a2d30 }, 0, 0.055, -0.08)
      P(g, box(0.03, 0.11, 0.04), 'metal_dark', { color: 0x1b1e21 }, 0, -0.09, weaponId === 'aug' ? 0.0 : -0.1, -0.06)
      break
    }
    case 'ssg08': case 'scar20': case 'g3sg1': {
      const chunky = weaponId !== 'ssg08'
      P(g, box(chunky ? 0.05 : 0.04, chunky ? 0.06 : 0.045, 0.28), 'metal_dark',
        { color: weaponId === 'g3sg1' ? 0x2d3326 : 0x232629 }, 0, 0.01, -0.08)
      P(g, cyl(0.01, 0.34), 'steel_blued', {}, 0, 0.018, -0.36, q(90))
      P(g, cyl(weaponId === 'ssg08' ? 0.015 : 0.018, 0.2, 12), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.065, -0.12, q(90))
      P(g, box(0.03, 0.07, 0.18), 'metal_dark', { color: 0x25282a }, 0, 0.0, 0.16)
      P(g, box(0.03, 0.1, 0.04), 'metal_dark', { color: 0x1b1e21 }, 0, -0.08, -0.02, 0.2)
      break
    }
    // ---- Phase 6 shotguns: barrel-over-tube silhouette; mag7 = box mag,
    // sawed-off = stubby wood pistol-grip
    case 'nova': case 'xm1014': {
      const long = weaponId === 'nova'
      P(g, box(0.042, 0.05, 0.2), 'polymer_black', { color: 0x232629 }, 0, 0.01, -0.05)
      P(g, cyl(0.009, long ? 0.3 : 0.24), 'steel_blued', {}, 0, 0.024, long ? -0.3 : -0.24, q(90))
      P(g, cyl(0.012, long ? 0.26 : 0.2, 10), 'metal_dark', { color: 0x232629 }, 0, -0.004, long ? -0.28 : -0.22, q(90))
      P(g, box(0.036, 0.045, long ? 0.1 : 0.08), 'polymer_black', { color: 0x25282a }, 0, -0.008, -0.2)
      P(g, box(0.032, 0.06, 0.12), 'polymer_black', { color: 0x26292c }, 0, 0.005, 0.1)
      break
    }
    // ---- Phase 7 MGs: heavy silhouette — long receiver, shrouded barrel,
    // under-box mag, bipod legs under the front
    case 'm249': case 'negev': {
      const long = weaponId === 'm249'
      P(g, box(0.052, 0.065, long ? 0.32 : 0.28), 'metal_dark',
        { color: long ? 0x2b3428 : 0x2a2d30 }, 0, 0.01, long ? -0.08 : -0.06)
      P(g, cyl(0.011, long ? 0.26 : 0.2), 'steel_blued', {}, 0, 0.018, long ? -0.36 : -0.29, q(90))
      P(g, cyl(long ? 0.017 : 0.023, 0.2, 12), 'metal_dark', { roughnessMul: 0.75, color: long ? 0x2b3428 : 0x2a2d30 }, 0, 0.018, long ? -0.31 : -0.26, q(90))
      // ammo box under the receiver front + latch ridge
      P(g, box(0.05, 0.11, 0.07), 'polymer_black', { color: long ? 0x1e2124 : 0x232629 }, 0, -0.06, long ? -0.16 : -0.13, long ? 0 : 0.1)
      P(g, box(0.054, 0.014, 0.076), 'metal_dark', { color: 0x141618 }, 0, -0.012, long ? -0.16 : -0.13, long ? 0 : 0.1)
      // folded bipod legs + top carry hint
      P(g, cyl(0.004, 0.09, 8), 'metal_dark', { color: 0x16181a }, 0.012, -0.03, long ? -0.38 : -0.31, q(90), q(9))
      P(g, cyl(0.004, 0.09, 8), 'metal_dark', { color: 0x16181a }, -0.012, -0.03, long ? -0.38 : -0.31, q(90), -q(9))
      P(g, box(0.014, 0.02, 0.1), 'metal_dark', { color: 0x1a1d20 }, 0, 0.058, long ? -0.1 : -0.08)
      P(g, box(0.034, 0.05, 0.13), 'polymer_black', { color: long ? 0x2b3428 : 0x25282a }, 0, 0.006, 0.1)
      break
    }
    case 'mag7': {
      P(g, box(0.05, 0.06, 0.24), 'polymer_black', { color: 0x2a2d30 }, 0, 0.01, -0.06)
      P(g, cyl(0.011, 0.16), 'steel_blued', {}, 0, 0.026, -0.26, q(90))
      P(g, box(0.034, 0.1, 0.05), 'metal_dark', { color: 0x1b1e21 }, 0, -0.07, -0.02, -0.1)
      P(g, box(0.04, 0.06, 0.09), 'polymer_black', { color: 0x25282a }, 0, 0.0, 0.09)
      break
    }
    case 'sawedoff': {
      P(g, box(0.038, 0.045, 0.16), 'metal_dark', { color: 0x3a2f26 }, 0, 0.01, -0.02)
      P(g, cyl(0.009, 0.2), 'steel_blued', {}, 0, 0.022, -0.2, q(90))
      P(g, cyl(0.011, 0.16, 10), 'metal_dark', { color: 0x2b2f33 }, 0, -0.002, -0.18, q(90))
      P(g, box(0.03, 0.09, 0.045), 'wood_laminate', { color: 0x5a3d1e }, 0, -0.06, 0.015, 0.45)
      break
    }
    case 'mp5':
      P(g, cyl(0.022, 0.22, 12), 'metal_dark', { color: 0x232629 }, 0, 0.01, -0.02, q(90))
      P(g, cyl(0.02, 0.16, 12), 'metal_dark', {}, 0, 0.01, -0.2, q(90))
      P(g, box(0.03, 0.08, 0.05), 'polymer_black', { color: 0x1f2224 }, 0, -0.07, 0, -0.1)
      P(g, box(0.032, 0.06, 0.14), 'polymer_black', { color: 0x25282a }, 0, 0, 0.16)
      break
    // ---- Phase 4 SMGs: compact silhouette, per-model proportion flavor
    case 'mp9': case 'mac10': case 'mp7': case 'ump45': {
      const long = weaponId === 'mp7' || weaponId === 'ump45'
      P(g, box(0.042, 0.055, long ? 0.26 : 0.20), 'polymer_black', { color: 0x26292c }, 0, 0.01, long ? -0.09 : -0.06)
      P(g, cyl(weaponId === 'mac10' ? 0.012 : 0.008, 0.06, 8), 'steel_blued', {}, 0, 0.01, long ? -0.24 : -0.19, q(90))
      if (weaponId === 'ump45') P(g, box(0.03, 0.16, 0.04), 'polymer_black', { color: 0x1f2224 }, 0, -0.09, -0.13, -0.05)
      P(g, box(0.03, 0.085, 0.045), 'polymer_black', { density: 9 }, 0, -0.05, 0.02, 0.2)
      P(g, box(0.032, 0.05, 0.10), 'polymer_black', { color: 0x25282a }, 0, 0.005, long ? 0.09 : 0.06)
      break
    }
    case 'p90':
      P(g, box(0.046, 0.07, 0.36), 'polymer_black', { color: 0x2a2d30 }, 0, 0.0, -0.12)
      P(g, box(0.02, 0.016, 0.24), 'polymer_black', { color: 0x1f2224 }, 0, 0.045, -0.08)
      P(g, cyl(0.007, 0.08, 8), 'steel_blued', {}, 0, 0.008, -0.34, q(90))
      P(g, box(0.026, 0.075, 0.04), 'polymer_black', { color: 0x1f2224 }, 0, -0.035, -0.02, 0.15)
      break
    case 'bizon':
      P(g, box(0.045, 0.05, 0.22), 'metal_dark', { color: 0x232629 }, 0, 0.01, -0.08)
      P(g, cyl(0.009, 0.13, 10), 'steel_blued', {}, 0, 0.018, -0.24, q(90))
      P(g, cyl(0.024, 0.17, 12), 'polymer_black', { color: 0x1f2224 }, 0, -0.03, -0.20, q(90))
      P(g, box(0.03, 0.085, 0.045), 'polymer_black', { density: 9 }, 0, -0.05, 0.02, 0.24)
      P(g, box(0.032, 0.045, 0.12), 'polymer_black', { color: 0x25282a }, 0, 0.005, 0.11)
      break
    case 'deagle':
      P(g, box(0.038, 0.045, 0.2), 'metal_dark', { roughnessMul: 0.8 }, 0, 0.015, -0.05)
      P(g, box(0.036, 0.09, 0.05), 'polymer_black', { density: 9 }, 0, -0.06, 0.03, 0.22)
      break
    case 'glock': case 'usp':
      P(g, box(0.032, 0.038, 0.16), 'metal_dark', { color: 0x26292c, roughnessMul: 0.8 }, 0, 0.01, -0.04)
      if (weaponId === 'usp') P(g, cyl(0.014, 0.1, 12), 'metal_dark', { roughnessMul: 0.75 }, 0, 0.01, -0.16, q(90))
      P(g, box(0.03, 0.08, 0.045), 'polymer_black', { density: 9 }, 0, -0.055, 0.02, 0.2)
      break
    // ---- Phase 3 pistols: generic low-detail shapes, per-family proportions
    case 'p250': case 'hkp2000': case 'cz75': case 'fiveseven': case 'tec9': {
      const long = weaponId === 'fiveseven' || weaponId === 'tec9'
      P(g, box(0.034, long ? 0.046 : 0.04, long ? 0.19 : 0.17), 'metal_dark',
        { color: weaponId === 'hkp2000' ? 0x303539 : 0x26292c, roughnessMul: 0.8 }, 0, 0.012, -0.05)
      if (weaponId === 'tec9') P(g, cyl(0.009, 0.06, 8), 'steel_blued', {}, 0, 0.012, -0.17, q(90))
      P(g, box(0.03, 0.085, 0.045), 'polymer_black', { density: 9 }, 0, -0.05, 0.02, weaponId === 'tec9' ? 0.1 : 0.22)
      break
    }
    case 'elites':
      for (const sgn of [1, -1]) {
        P(g, box(0.03, 0.036, 0.17), 'metal_dark', { color: 0x2c3033, roughnessMul: 0.8 }, sgn * 0.045, 0.012, -0.04)
        P(g, cyl(0.007, 0.024, 8), 'steel_blued', { roughnessMul: 0.4, metalness: 0.95 }, sgn * 0.045, 0.016, -0.135, q(90))
        P(g, box(0.026, 0.075, 0.042), 'polymer_black', { density: 9 }, sgn * 0.05, -0.042, 0.02, 0.2)
      }
      break
    case 'revolver':
      P(g, box(0.03, 0.04, 0.07), 'steel_blued', { color: 0x2c3033 }, 0, 0.005, -0.01)
      P(g, cyl(0.018, 0.05, 12), 'steel_blued', { roughnessMul: 0.6 }, 0, 0.012, -0.055, q(90))
      P(g, cyl(0.009, 0.13, 10), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.02, -0.13, q(90))
      P(g, box(0.03, 0.085, 0.045), 'polymer_black', { density: 9, color: 0x1f2224 }, 0, -0.05, 0.015, 0.28)
      break
    case 'taser':
      P(g, box(0.045, 0.05, 0.13), 'polymer_black', { color: 0x222527 }, 0, 0.008, -0.035)
      P(g, box(0.047, 0.016, 0.12), 'polymer_black', { color: 0xc9a227, roughnessMul: 0.6 }, 0, 0.04, -0.035)
      P(g, box(0.032, 0.085, 0.045), 'polymer_black', { density: 9 }, 0, -0.048, 0.015, 0.22)
      break
    case 'knife':
      P(g, box(0.01, 0.028, 0.14), 'metal_dark', { color: 0xcdd3d9, metalness: 1.0, roughnessMul: 0.35 }, 0, 0.01, -0.1)
      P(g, box(0.02, 0.03, 0.08), 'polymer_black', { density: 9 }, 0, 0, 0.02)
      break
    case 'c4':
      P(g, box(0.13, 0.05, 0.16), 'enamel_od', { color: 0x5a5c42, roughnessMul: 1.1 }, 0, 0, -0.02)
      basic(0xff2020, g, box(0.01, 0.006, 0.01), 0.02, 0.028, 0.04)
      break
    case 'he':
      P(g, new THREE.SphereGeometry(0.045, 10, 8), 'enamel_od', { color: 0x39402c }, 0, 0.01, -0.06)
      break
    case 'flash':
      P(g, cyl(0.026, 0.1, 10), 'metal_dark', { color: 0x8b9096, roughnessMul: 0.4 }, 0, 0.01, -0.06)
      P(g, cyl(0.027, 0.016, 10), 'metal_dark', { color: 0x3556a8 }, 0, 0.03, -0.06)
      break
    case 'smoke':
      P(g, cyl(0.029, 0.11, 10), 'metal_dark', { color: 0x5b6157, roughnessMul: 0.55 }, 0, 0.01, -0.06)
      P(g, cyl(0.03, 0.015, 10), 'metal_dark', { color: 0x9c3b30 }, 0, 0.025, -0.06)
      break
    case 'molotov':
      P(g, cyl(0.03, 0.11, 10), 'metal_dark', { color: 0x7a4f1e, roughnessMul: 0.3 }, 0, 0.01, -0.06)
      P(g, box(0.016, 0.04, 0.016), 'polymer_black', { color: 0x4a6612, density: 6 }, 0, 0.08, -0.06)
      break
    case 'inc':
      P(g, cyl(0.03, 0.1, 10), 'metal_dark', { color: 0x6a3b1c, roughnessMul: 0.45 }, 0, 0.01, -0.06)
      P(g, cyl(0.031, 0.014, 10), 'metal_dark', { color: 0xc7c2ba }, 0, 0.008, -0.06)
      break
    case 'decoy':
      P(g, box(0.06, 0.05, 0.045), 'polymer_black', { color: 0x4a4238 }, 0, 0.01, -0.06)
      P(g, cyl(0.004, 0.07, 6), 'metal_dark', { color: 0x1c1c1c }, 0, 0.06, -0.05, q(12))
      break
    default:
      P(g, box(0.045, 0.06, 0.4), 'metal_dark', {}, 0, 0, -0.1)
  }
  return g
}
